import { canvasItemId } from "@ai-matrx/canvas";
const CONVERSATION_DOCUMENTS_KIND = "conversation-documents";
const SCRATCHPAD_KIND = "global-scratchpad";
const CONVERSATION_CONTEXT_KIND = "conversation-context";
const CONVERSATION_LISTS_KIND = "conversation-lists";
