import { createAsyncThunk } from "@reduxjs/toolkit";
import {
  callConversationFork
} from "../../../../../host/server/call-api.js";
import { loadConversation } from "../../thunks/load-conversation.thunk.js";
import { setFocus } from "../../conversation-focus/conversation-focus.slice.js";
import { markCacheBypass } from "../cache-bypass.slice.js";
import { invalidateConversationCache } from "../invalidate-conversation-cache.thunk.js";
const forkConversationServer = createAsyncThunk(
  "conversations/forkServer",
  async ({
    conversationId,
    selector,
    title,
    surfaceKey,
    retainForkOnHydrationFailure = false
  }, { dispatch, rejectWithValue }) => {
    const body = {
      up_to_position: selector?.upToPosition ?? null,
      from_message_id: selector?.fromMessageId ?? null,
      exclusive: selector?.exclusive ?? false,
      title: title ?? null
    };
    const result = await dispatch(
      callConversationFork({ conversationId, body })
    );
    if (result.error) {
      return rejectWithValue({
        message: result.error.message ?? `Fork endpoint failed: HTTP ${result.error.status ?? "unknown"}`
      });
    }
    const data = result.data;
    if (!data?.conversation_id) {
      return rejectWithValue({
        message: "Fork endpoint returned no conversation_id"
      });
    }
    let hydrationError;
    try {
      await dispatch(
        loadConversation({
          conversationId: data.conversation_id,
          expectMaterialized: true
        })
      ).unwrap();
    } catch (err) {
      console.error(
        "[forkConversationServer] loadConversation after fork failed",
        err
      );
      hydrationError = `Fork succeeded but rehydration failed: ${err instanceof Error ? err.message : String(err)}`;
      if (!retainForkOnHydrationFailure) {
        return rejectWithValue({ message: hydrationError });
      }
    }
    if (surfaceKey) {
      dispatch(setFocus({ surfaceKey, conversationId: data.conversation_id }));
    }
    dispatch(markCacheBypass({ conversationId, conversation: true }));
    dispatch(
      markCacheBypass({
        conversationId: data.conversation_id,
        conversation: true
      })
    );
    void dispatch(invalidateConversationCache({ conversationId }));
    void dispatch(
      invalidateConversationCache({
        conversationId: data.conversation_id
      })
    );
    return {
      conversationId: data.conversation_id,
      forkedFromId: data.forked_from_id,
      forkedAtPosition: data.forked_at_position ?? null,
      messageCount: data.message_count,
      hydrationError
    };
  }
);
export {
  forkConversationServer
};
