"use client";
import { toast } from "../../../../host/notify.js";
const USER_EDIT_ACTIONS = [
  { id: "save", label: "Save only", variant: "secondary" },
  { id: "resubmit", label: "Save & resubmit" },
  { id: "fork", label: "Fork & resubmit" }
];
async function routeUserEditAction(dispatch, {
  actionId,
  conversationId,
  messageId,
  newContent,
  surfaceKey
}) {
  try {
    if (actionId === "save") {
      const { editMessageText } = await import("../../../redux/execution-system/message-crud/edit-message-text.thunk.js");
      await dispatch(
        editMessageText({ conversationId, messageId, newContent })
      ).unwrap();
      toast.success("Message saved");
    } else if (actionId === "resubmit") {
      const { overwriteAndResend } = await import("../../../redux/execution-system/message-crud/overwrite-and-resend.thunk.js");
      await dispatch(
        overwriteAndResend({ conversationId, messageId, newContent })
      ).unwrap();
    } else if (actionId === "fork") {
      const { forkAndResubmitFromMessage } = await import("../../../redux/execution-system/message-crud/fork-and-resubmit-from-message.thunk.js");
      await dispatch(
        forkAndResubmitFromMessage({
          conversationId,
          messageId,
          newContent,
          surfaceKey
        })
      ).unwrap();
    } else {
      throw new Error(`Unknown editor action: ${actionId}`);
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : typeof err === "object" && err && "message" in err && typeof err.message === "string" ? err.message : "Edit failed";
    console.error(`[routeUserEditAction] "${actionId}" failed`, err);
    toast.error(message);
    throw err;
  }
}
export {
  USER_EDIT_ACTIONS,
  routeUserEditAction
};
