import { createAsyncThunk } from "@reduxjs/toolkit";
import { supabase } from "../../../host/db.js";
import { operationFailed } from "@ai-matrx/kit/errors";
import { ensureEffectiveKnob } from "../../../host/prefs.js";
import { selectActiveOrganizationId } from "../../../context/sources/scopes.js";
import {
  setTrashLoading,
  setTrashSuccess,
  setTrashError,
  removeFromTrash,
  prependConversation
} from "./conversation-list.slice.js";
import { upsertConversationIntoScopes } from "../conversation-history/slice.js";
import { getUserId } from "../../../host/identity.js";
import { setConversationArchived } from "./conversation-row-actions.thunks.js";
const CONVERSATION_TRASH_PAGE_SIZE_KNOB = {
  feature: "agents.conversations",
  key: "trash_page_size"
};
const fetchArchivedConversations = createAsyncThunk(
  "conversationList/fetchTrashed",
  async (rawArgs, { dispatch, getState, rejectWithValue }) => {
    dispatch(setTrashLoading());
    const viewerId = getUserId();
    let limit = rawArgs?.limit;
    if (limit === void 0) {
      const organizationId = selectActiveOrganizationId(getState());
      try {
        if (!organizationId) {
          throw new Error(
            "no organization is active yet, so its page size cannot be resolved"
          );
        }
        const raw = await ensureEffectiveKnob(
          organizationId,
          viewerId ?? null,
          CONVERSATION_TRASH_PAGE_SIZE_KNOB
        );
        const resolved = typeof raw === "number" ? raw : Number(raw);
        if (!Number.isFinite(resolved) || resolved <= 0) {
          throw new Error(
            `it resolves to ${JSON.stringify(raw)}, which is not a number of conversations`
          );
        }
        limit = resolved;
      } catch (error2) {
        const message = `The archive could not be opened: the setting that decides how many archived conversations one page shows ("${CONVERSATION_TRASH_PAGE_SIZE_KNOB.feature}.${CONVERSATION_TRASH_PAGE_SIZE_KNOB.key}") could not be read \u2014 ${error2 instanceof Error ? error2.message : String(error2)}.`;
        dispatch(setTrashError(message));
        return rejectWithValue({ message });
      }
    }
    let query = supabase.schema("chat").from("conversation").select(
      "id, title, description, status, message_count, initial_agent_id, last_model_id, source_app, source_feature, created_at, updated_at, deleted_at, exclude_from_kg"
    ).or("deleted_at.not.is.null,status.eq.archived").eq("is_ephemeral", false).order("updated_at", { ascending: false }).limit(limit);
    if (viewerId) query = query.eq("created_by", viewerId);
    const { data, error } = await query;
    if (error) {
      const message = operationFailed("open the archive", error).message;
      dispatch(setTrashError(message));
      return rejectWithValue({ message });
    }
    const items = (data ?? []).map((row) => ({
      conversationId: row.id,
      title: row.title ?? null,
      description: row.description ?? null,
      updatedAt: row.deleted_at ?? row.updated_at,
      createdAt: row.created_at,
      status: row.status,
      messageCount: row.message_count ?? 0,
      // Pins and knowledge-graph state are irrelevant in the trash and are not
      // read here; a restored row picks its real values up on the next list load.
      isFavorite: false,
      excludeFromKg: row.exclude_from_kg ?? false,
      agentId: row.initial_agent_id ?? null,
      lastModelId: row.last_model_id ?? null,
      sourceApp: row.source_app ?? void 0,
      sourceFeature: row.source_feature ?? void 0,
      deletedAt: row.deleted_at ?? null
    }));
    dispatch(setTrashSuccess({ items }));
    return { items };
  }
);
const restoreConversation = createAsyncThunk(
  "conversationList/restore",
  async ({ conversationId }, { dispatch, getState, rejectWithValue }) => {
    const item = getState().conversationList.trashByConversationId[conversationId];
    const wasDeleted = !item || Boolean(item.deletedAt);
    const wasArchived = item?.status === "archived";
    if (wasDeleted) {
      const { data, error } = await supabase.rpc("cx_restore_conversation", {
        p_conversation_id: conversationId
      });
      if (error) {
        return rejectWithValue({
          message: operationFailed("restore this conversation", error).message
        });
      }
      if (data !== true) {
        return rejectWithValue({
          message: operationFailed("restore this conversation").message
        });
      }
    }
    if (wasArchived) {
      const unarchived = await dispatch(
        setConversationArchived({ conversationId, archived: false })
      );
      if (setConversationArchived.rejected.match(unarchived)) {
        return rejectWithValue({
          message: unarchived.payload?.message ?? operationFailed("restore this conversation").message
        });
      }
    }
    dispatch(removeFromTrash(conversationId));
    if (item) {
      const row = {
        ...item,
        status: wasArchived ? "active" : item.status,
        deletedAt: null
      };
      dispatch(prependConversation(row));
      dispatch(
        upsertConversationIntoScopes({
          row,
          agentId: row.agentId ?? ""
        })
      );
    }
    return { conversationId, restored: true };
  }
);
export {
  fetchArchivedConversations,
  restoreConversation
};
