import { createAsyncThunk } from "@reduxjs/toolkit";
import { setPreference, selectPreferencesLoaded } from "../../../../host/prefs.js";
import {
  applyAgentWorkingDocContent,
  markWorkingDocMaterialized,
  removeWorkingDocEntry,
  addAttachedScratchpad,
  removeAttachedScratchpad,
  setAttachedScratchpads,
  reservedWorkingDocumentId,
  scratchScopeId,
  workingDocKey,
  setWorkingDocBinding,
  setWorkingDocEnabled,
  setWorkingDocTitle,
  markActiveScratchpadResolved,
  markWorkingDocsRestored
} from "./instance-working-document.slice.js";
import { selectActiveScratchpadId } from "./instance-working-document.selectors.js";
import { setConversationDocumentEnabledThunk } from "./instance-working-document.thunks.js";
import {
  getCxWorkingDocumentById,
  linkDocumentToConversation,
  listConversationDocuments,
  listUserDocuments,
  softDeleteWorkingDocument,
  unlinkDocumentFromConversation
} from "./cx-working-document.service.js";
import { getActiveOrgId } from "../../../../host/org.js";
function setActivePreference(dispatch, id) {
  dispatch(
    setPreference({ module: "scratchpad", preference: "activeId", value: id })
  );
}
function applyScratchpadDoc(dispatch, doc) {
  const scope = scratchScopeId(doc.id);
  dispatch(setWorkingDocEnabled({ conversationId: scope, kind: "scratch", enabled: true }));
  dispatch(
    setWorkingDocBinding({
      conversationId: scope,
      kind: "scratch",
      binding: { kind: "cx_working_document", id: doc.id, label: doc.title }
    })
  );
  dispatch(
    markWorkingDocMaterialized({
      conversationId: scope,
      kind: "scratch",
      version: doc.version
    })
  );
  if (doc.title) {
    dispatch(
      setWorkingDocTitle({ conversationId: scope, kind: "scratch", title: doc.title })
    );
  }
  dispatch(
    applyAgentWorkingDocContent({
      conversationId: scope,
      kind: "scratch",
      content: doc.content ?? ""
    })
  );
}
function reserveScratchpadEntry(dispatch, documentId) {
  const scope = scratchScopeId(documentId);
  dispatch(setWorkingDocEnabled({ conversationId: scope, kind: "scratch", enabled: true }));
  dispatch(
    setWorkingDocBinding({
      conversationId: scope,
      kind: "scratch",
      binding: { kind: "cx_working_document", id: documentId, label: null }
    })
  );
}
let activeHydrateInFlight = null;
const hydrateActiveScratchpadThunk = createAsyncThunk(
  "scratchpad/hydrateActive",
  async (args, { dispatch, getState }) => {
    if (activeHydrateInFlight && !args?.force) return activeHydrateInFlight;
    if (!args?.force && getState().instanceWorkingDocument.activeScratchpadResolved) return;
    const run = (async () => {
      for (let i = 0; i < 30 && !selectPreferencesLoaded(getState()); i++) {
        await new Promise((r) => setTimeout(r, 100));
      }
      let activeId = selectActiveScratchpadId(getState());
      if (activeId && getState().instanceWorkingDocument.byKey[workingDocKey(scratchScopeId(activeId), "scratch")]?.materialized) {
        return;
      }
      if (!activeId) {
        try {
          const existing = await listUserDocuments("scratch", 1);
          if (existing[0]) {
            activeId = existing[0].id;
            setActivePreference(dispatch, activeId);
            applyScratchpadDoc(dispatch, existing[0]);
            return;
          }
        } catch (err) {
          console.error("[scratchpad] hydrate: list failed", err);
          throw err;
        }
        return;
      }
      try {
        const doc = await getCxWorkingDocumentById(activeId);
        if (doc) {
          applyScratchpadDoc(dispatch, doc);
        } else {
          reserveScratchpadEntry(dispatch, activeId);
        }
      } catch (err) {
        console.error("[scratchpad] hydrate: load failed", { activeId, err });
        throw err;
      }
    })();
    activeHydrateInFlight = run.then(() => {
      dispatch(markActiveScratchpadResolved());
    }).finally(() => {
      activeHydrateInFlight = null;
    });
    return activeHydrateInFlight;
  }
);
const createScratchpadThunk = createAsyncThunk("scratchpad/create", async (args, { dispatch }) => {
  const id = crypto.randomUUID();
  reserveScratchpadEntry(dispatch, id);
  if (args?.makeActive !== false) setActivePreference(dispatch, id);
  return id;
});
const setScratchpadGateThunk = createAsyncThunk(
  "scratchpad/setGate",
  async ({ conversationId, enabled }, { dispatch, getState }) => {
    if (enabled && !selectActiveScratchpadId(getState())) {
      await dispatch(createScratchpadThunk());
    }
    await dispatch(
      setConversationDocumentEnabledThunk({
        conversationId,
        kind: "scratch",
        enabled
      })
    );
  }
);
const setActiveScratchpadThunk = createAsyncThunk("scratchpad/setActive", async ({ documentId }, { dispatch, getState }) => {
  setActivePreference(dispatch, documentId);
  const scope = scratchScopeId(documentId);
  const loaded = getState().instanceWorkingDocument.byKey[workingDocKey(scope, "scratch")]?.materialized;
  if (loaded) return;
  try {
    const doc = await getCxWorkingDocumentById(documentId);
    if (doc) applyScratchpadDoc(dispatch, doc);
    else reserveScratchpadEntry(dispatch, documentId);
  } catch (err) {
    console.error("[scratchpad] setActive: load failed", { documentId, err });
    throw err;
  }
});
const deleteScratchpadThunk = createAsyncThunk("scratchpad/delete", async ({ documentId }, { dispatch, getState }) => {
  const scope = scratchScopeId(documentId);
  const wasMaterialized = getState().instanceWorkingDocument.byKey[workingDocKey(scope, "scratch")]?.materialized;
  if (wasMaterialized) {
    try {
      await softDeleteWorkingDocument(documentId);
    } catch (err) {
      console.error("[scratchpad] delete failed", { documentId, err });
      throw err;
    }
  }
  dispatch(removeWorkingDocEntry({ conversationId: scope, kind: "scratch" }));
  if (selectActiveScratchpadId(getState()) === documentId) {
    setActivePreference(dispatch, null);
    try {
      const remaining = await listUserDocuments("scratch", 1);
      if (remaining[0]) {
        setActivePreference(dispatch, remaining[0].id);
        applyScratchpadDoc(dispatch, remaining[0]);
      }
    } catch (err) {
      console.error("[scratchpad] delete: successor pick failed", err);
    }
  }
});
function orgForConversation(state, conversationId) {
  return state.conversations.byConversationId[conversationId]?.organizationId ?? getActiveOrgId();
}
const attachScratchpadToConversationThunk = createAsyncThunk(
  "scratchpad/attach",
  async ({ conversationId, documentId }, { dispatch, getState }) => {
    try {
      const doc = await getCxWorkingDocumentById(documentId);
      if (!doc) return;
      applyScratchpadDoc(dispatch, doc);
      const orgId = orgForConversation(getState(), conversationId);
      if (orgId) {
        await linkDocumentToConversation({
          documentId,
          conversationId,
          organizationId: orgId,
          kind: "scratch",
          enabled: true
        });
      }
      dispatch(addAttachedScratchpad({ conversationId, documentId }));
    } catch (err) {
      console.error("[scratchpad] attach failed", {
        conversationId,
        documentId,
        err
      });
    }
  }
);
const detachScratchpadFromConversationThunk = createAsyncThunk(
  "scratchpad/detach",
  async ({ conversationId, documentId }, { dispatch }) => {
    dispatch(removeAttachedScratchpad({ conversationId, documentId }));
    try {
      await unlinkDocumentFromConversation(documentId, conversationId);
    } catch (err) {
      console.error("[scratchpad] detach failed", {
        conversationId,
        documentId,
        err
      });
    }
  }
);
const hydrateAttachedScratchpadsThunk = createAsyncThunk(
  "scratchpad/hydrateAttached",
  async ({ conversationId }, { dispatch, getState }) => {
    if (getState().instanceWorkingDocument.restoredByConversation[conversationId]?.attachedScratch) return;
    let links;
    try {
      links = await listConversationDocuments(conversationId);
    } catch (err) {
      console.error("[scratchpad] hydrateAttached: list failed", {
        conversationId,
        err
      });
      throw err;
    }
    const activeId = selectActiveScratchpadId(getState());
    const gateId = reservedWorkingDocumentId(conversationId, "scratch");
    const ids = links.filter(
      (l) => l.kind === "scratch" && l.enabled && l.documentId !== activeId && l.documentId !== gateId
    ).map((l) => l.documentId);
    const resolved = [];
    let failed = 0;
    await Promise.all(
      ids.map(async (id) => {
        try {
          const doc = await getCxWorkingDocumentById(id);
          if (doc) {
            applyScratchpadDoc(dispatch, doc);
            resolved.push(id);
          }
        } catch (err) {
          failed += 1;
          console.error("[scratchpad] hydrateAttached: load failed", {
            id,
            err
          });
        }
      })
    );
    dispatch(setAttachedScratchpads({ conversationId, documentIds: resolved }));
    if (failed === 0) dispatch(markWorkingDocsRestored({ conversationId, part: "attachedScratch" }));
    if (failed > 0) {
      throw new Error(`${failed} attached scratchpad${failed === 1 ? "" : "s"} could not be read`);
    }
  }
);
export {
  attachScratchpadToConversationThunk,
  createScratchpadThunk,
  deleteScratchpadThunk,
  detachScratchpadFromConversationThunk,
  hydrateActiveScratchpadThunk,
  hydrateAttachedScratchpadsThunk,
  setActiveScratchpadThunk,
  setScratchpadGateThunk
};
