import { createAsyncThunk } from "@reduxjs/toolkit";
import { editMessage } from "./edit-message.thunk.js";
import { mergeEditedText } from "./content-blocks.util.js";
const editMessageText = createAsyncThunk(
  "messages/editMessageText",
  async ({ conversationId, messageId, newContent }, { dispatch, getState }) => {
    const existing = getState().messages.byConversationId[conversationId]?.byId?.[messageId]?.content;
    await dispatch(
      editMessage({
        conversationId,
        messageId,
        newContent: mergeEditedText(existing, newContent)
      })
    ).unwrap();
  }
);
export {
  editMessageText
};
