import { createSelector } from "@reduxjs/toolkit";
const selectObservationalMemoryState = (conversationId) => (state) => {
  if (!conversationId) return void 0;
  return state.observationalMemory.byConversationId[conversationId];
};
const selectAllObservationalMemoryConversations = (state) => state.observationalMemory.byConversationId;
const selectMemoryMetadata = (conversationId) => (state) => {
  if (!conversationId) return null;
  return state.observationalMemory.byConversationId[conversationId]?.metadata ?? null;
};
const selectIsMemoryEnabledForConversation = (conversationId) => (state) => {
  if (!conversationId) return false;
  return state.observationalMemory.byConversationId[conversationId]?.isEnabled ?? false;
};
const selectMemoryModelForConversation = (conversationId) => (state) => {
  if (!conversationId) return null;
  return state.observationalMemory.byConversationId[conversationId]?.metadata?.model ?? null;
};
const selectMemoryScopeForConversation = (conversationId) => (state) => {
  if (!conversationId) return null;
  return state.observationalMemory.byConversationId[conversationId]?.metadata?.scope ?? null;
};
const selectMemoryDegraded = (conversationId) => (state) => {
  if (!conversationId) return false;
  return state.observationalMemory.byConversationId[conversationId]?.degraded ?? false;
};
const selectMemoryLastError = (conversationId) => (state) => {
  if (!conversationId) return null;
  return state.observationalMemory.byConversationId[conversationId]?.lastError ?? null;
};
const EMPTY_EVENTS = Object.freeze([]);
const selectMemoryEvents = (conversationId) => (state) => {
  if (!conversationId) return EMPTY_EVENTS;
  return state.observationalMemory.byConversationId[conversationId]?.events ?? EMPTY_EVENTS;
};
const selectMemoryCounters = (conversationId) => (state) => {
  if (!conversationId) return null;
  return state.observationalMemory.byConversationId[conversationId]?.counters ?? null;
};
const selectRecentMemoryEvents = (conversationId, limit = 50) => createSelector(
  [
    (state) => conversationId ? state.observationalMemory.byConversationId[conversationId]?.events ?? EMPTY_EVENTS : EMPTY_EVENTS
  ],
  (events) => {
    if (events.length === 0) return [];
    const slice = events.slice(Math.max(0, events.length - limit));
    slice.reverse();
    return slice;
  }
);
const selectMemoryCostSummary = (conversationId) => (state) => {
  if (!conversationId) return null;
  return state.observationalMemory.byConversationId[conversationId]?.costSummary ?? null;
};
const selectMemoryCostFetchState = (conversationId) => (state) => {
  if (!conversationId) return null;
  return state.observationalMemory.byConversationId[conversationId]?.costFetch ?? null;
};
export {
  selectAllObservationalMemoryConversations,
  selectIsMemoryEnabledForConversation,
  selectMemoryCostFetchState,
  selectMemoryCostSummary,
  selectMemoryCounters,
  selectMemoryDegraded,
  selectMemoryEvents,
  selectMemoryLastError,
  selectMemoryMetadata,
  selectMemoryModelForConversation,
  selectMemoryScopeForConversation,
  selectObservationalMemoryState,
  selectRecentMemoryEvents
};
