import { openOverlay, CHAT_WINDOWS } from "../../../../host/windows.js";
function openStructuredRawViewer(dispatch, { content, messageId, metadata }) {
  dispatch(
    openOverlay({
      overlayId: CHAT_WINDOWS.fullScreenEditor,
      instanceId: `raw-view-${messageId ?? "unknown"}`,
      data: {
        content,
        mode: "free",
        // Deliberately NO conversationId/messageId: the bridge's self-handle
        // save path keys off those ids, and this view must never write back.
        tabs: ["write", "preview"],
        initialTab: "write",
        analysisData: metadata ?? void 0,
        title: "Structured content (read-only raw)",
        description: "This message's stored content is structured data (media blocks or other non-text payload), shown here exactly as stored. It cannot be edited as text \u2014 copy it to inspect or reuse.",
        showSaveButton: false,
        showCopyButton: true
      }
    })
  );
}
export {
  openStructuredRawViewer
};
