const selectFocusedConversation = (surfaceKey) => (state) => state.conversationFocus?.bySurface[surfaceKey]?.input ?? null;
const selectInputConversation = selectFocusedConversation;
const selectDisplayConversation = (surfaceKey) => (state) => state.conversationFocus?.bySurface[surfaceKey]?.display ?? null;
const selectIsFocusSplit = (surfaceKey) => (state) => {
  const entry = state.conversationFocus?.bySurface[surfaceKey];
  if (!entry) return false;
  return entry.display !== entry.input;
};
const selectAllSurfaceFocus = (state) => state.conversationFocus?.bySurface;
const selectLastFocusedSurfaceKey = (state) => state.conversationFocus?.lastSurfaceKey ?? null;
const selectLastFocusedInputConversation = (state) => {
  const key = state.conversationFocus?.lastSurfaceKey;
  if (!key) return null;
  return state.conversationFocus?.bySurface[key]?.input ?? null;
};
const selectLastFocusedDisplayConversation = (state) => {
  const key = state.conversationFocus?.lastSurfaceKey;
  if (!key) return null;
  return state.conversationFocus?.bySurface[key]?.display ?? null;
};
export {
  selectAllSurfaceFocus,
  selectDisplayConversation,
  selectFocusedConversation,
  selectInputConversation,
  selectIsFocusSplit,
  selectLastFocusedDisplayConversation,
  selectLastFocusedInputConversation,
  selectLastFocusedSurfaceKey
};
