const FILL_FORM_INSTRUCTION = "Fill in the fields below and run.";
const TYPE_MESSAGE_INSTRUCTION = "Type a message below to start.";
function emptyStateInstruction({
  formFieldCount,
  formShown,
  hasDescription
}) {
  if (formShown && formFieldCount > 0) return FILL_FORM_INSTRUCTION;
  return hasDescription ? null : TYPE_MESSAGE_INSTRUCTION;
}
export {
  FILL_FORM_INSTRUCTION,
  TYPE_MESSAGE_INSTRUCTION,
  emptyStateInstruction
};
