import { createSelector } from "@reduxjs/toolkit";
const EMPTY_TASKS = [];
const EMPTY_TODOS = [];
const DEFAULT_BUCKET = {
  plan: null,
  tasks: EMPTY_TASKS,
  userTodos: EMPTY_TODOS,
  status: "idle"
};
const selectAgentListsBucket = (conversationId) => (state) => state.agentLists?.byConversationId[conversationId] ?? DEFAULT_BUCKET;
const selectAgentListsStatus = (conversationId) => (state) => state.agentLists?.byConversationId[conversationId]?.status ?? "idle";
const selectAgentListsError = (conversationId) => (state) => {
  const bucket = state.agentLists?.byConversationId[conversationId];
  return bucket?.status === "error" ? bucket.error ?? "The read failed." : null;
};
const selectAgentPlan = (conversationId) => (state) => state.agentLists?.byConversationId[conversationId]?.plan ?? null;
const selectAgentTasks = (conversationId) => (state) => state.agentLists?.byConversationId[conversationId]?.tasks ?? EMPTY_TASKS;
const selectUserTodosForConversation = (conversationId) => (state) => state.agentLists?.byConversationId[conversationId]?.userTodos ?? EMPTY_TODOS;
const selectAgentTaskCounts = (conversationId) => createSelector(
  (state) => state.agentLists?.byConversationId[conversationId]?.tasks ?? EMPTY_TASKS,
  (tasks) => {
    let done = 0;
    let inProgress = 0;
    for (const t of tasks) {
      if (t.status === "done") done++;
      else if (t.status === "in_progress") inProgress++;
    }
    return {
      total: tasks.length,
      done,
      inProgress,
      pending: tasks.length - done - inProgress
    };
  }
);
const selectUserTodoCounts = (conversationId) => createSelector(
  (state) => state.agentLists?.byConversationId[conversationId]?.userTodos ?? EMPTY_TODOS,
  (todos) => {
    let done = 0;
    for (const t of todos) if (t.done) done++;
    return { total: todos.length, done, open: todos.length - done };
  }
);
const EMPTY_BY_CONVERSATION = {};
const selectAllConversationLists = (state) => state.agentLists?.byConversationId ?? EMPTY_BY_CONVERSATION;
const selectHasAgentListsContent = (conversationId) => (state) => {
  const bucket = state.agentLists?.byConversationId[conversationId];
  if (!bucket) return false;
  return bucket.plan !== null || bucket.tasks.length > 0 || bucket.userTodos.length > 0;
};
export {
  selectAgentListsBucket,
  selectAgentListsError,
  selectAgentListsStatus,
  selectAgentPlan,
  selectAgentTaskCounts,
  selectAgentTasks,
  selectAllConversationLists,
  selectHasAgentListsContent,
  selectUserTodoCounts,
  selectUserTodosForConversation
};
