"use client";
import { useRef, useState, useCallback } from "react";
function useDomCapturePrint() {
  const captureRef = useRef(null);
  const [isCapturing, setIsCapturing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState(null);
  const captureAsPDF = useCallback(async (options = {}) => {
    const el = captureRef.current;
    if (!el) {
      setError("Nothing to capture \u2014 captureRef is not attached to any element.");
      return;
    }
    setIsCapturing(true);
    setProgress(0);
    setError(null);
    let releaseRenderAll = null;
    let restoreFrames = null;
    try {
      const { renderAllDiagrams } = await import("@ai-matrx/rich-content/mermaid/lazy-draw");
      releaseRenderAll = (await renderAllDiagrams()).release;
      const { framesToPictures } = await import("../utils/frame-print.js");
      restoreFrames = (await framesToPictures(el)).restore;
      const [{ captureDocumentPdf }, { downloadFile }] = await Promise.all([
        import("@ai-matrx/alchemy/operate/capture"),
        import("@ai-matrx/kit/download")
      ]);
      const { filename = "ai-response", ...captureOptions } = options;
      const pdf = await captureDocumentPdf(el, {
        scale: 2,
        ...captureOptions,
        onProgress: (page, total) => {
          setProgress(Math.round(page / Math.max(total, 1) * 100));
          options.onProgress?.(page, total);
        }
      });
      downloadFile(`${filename}.pdf`, pdf, "application/pdf");
    } catch (err) {
      const msg = err instanceof Error ? err.message : "PDF export failed";
      setError(msg);
    } finally {
      restoreFrames?.();
      releaseRenderAll?.();
      setIsCapturing(false);
      setProgress(0);
    }
  }, []);
  return { captureRef, isCapturing, progress, captureAsPDF, error };
}
export {
  useDomCapturePrint
};
