"use client";
import { selectAgentById } from "../agent-definition/selectors.js";
import { createSelector } from "@reduxjs/toolkit";
import {
  CONVERSATION_LIST_TTL_MS,
  conversationListCacheKey
} from "./conversation-list.types.js";
import { selectAgentIdFromInstance } from "../execution-system/conversations/conversations.selectors.js";
const EMPTY_ITEMS = [];
const EMPTY_IDS = [];
const selectSlice = (state) => state.conversationList;
const selectGlobalConversationList = createSelector(
  [selectSlice],
  (slice) => {
    if (slice.allConversationIds.length === 0) return EMPTY_ITEMS;
    const out = [];
    for (const id of slice.allConversationIds) {
      const item = slice.byConversationId[id];
      if (item) out.push(item);
    }
    return out.length === 0 ? EMPTY_ITEMS : out;
  }
);
const selectGlobalConversationIds = (state) => state.conversationList.allConversationIds;
const selectGlobalListStatus = (state) => state.conversationList.globalStatus;
const selectGlobalListError = (state) => state.conversationList.globalError;
const selectGlobalListHasMore = (state) => state.conversationList.globalHasMore;
const selectGlobalListLastFetchedAt = (state) => state.conversationList.globalLastFetchedAt;
const selectGlobalListIsFresh = (ttlMs = CONVERSATION_LIST_TTL_MS) => (state) => {
  const { globalLastFetchedAt, globalStatus } = state.conversationList;
  if (globalStatus === "loading") return true;
  if (!globalLastFetchedAt) return false;
  return Date.now() - globalLastFetchedAt < ttlMs;
};
const selectConversationListItemById = (conversationId) => (state) => state.conversationList.byConversationId[conversationId] ?? null;
const selectConversationIsPending = (conversationId) => (state) => state.conversationList.pendingOperations.includes(conversationId);
const selectAgentConversationsCache = (agentId, versionFilter) => (state) => state.conversationList.agentCaches[conversationListCacheKey(agentId, versionFilter)];
function makeSelectAgentConversationList(agentId, versionFilter) {
  const key = conversationListCacheKey(agentId, versionFilter);
  return createSelector(
    [(state) => state.conversationList],
    (slice) => {
      const entry = slice.agentCaches[key];
      if (!entry) {
        return {
          conversations: EMPTY_ITEMS,
          archived: EMPTY_ITEMS,
          status: "idle",
          error: null,
          fetchedAt: null
        };
      }
      const items = [];
      const archived = [];
      for (const id of entry.conversationIds) {
        const item = slice.byConversationId[id];
        if (!item) continue;
        if (item.status === "archived") archived.push(item);
        else items.push(item);
      }
      return {
        conversations: items.length === 0 ? EMPTY_ITEMS : items,
        archived: archived.length === 0 ? EMPTY_ITEMS : archived,
        status: entry.status,
        error: entry.error,
        fetchedAt: entry.fetchedAt
      };
    }
  );
}
const selectAgentConversationIds = (agentId, versionFilter) => (state) => state.conversationList.agentCaches[conversationListCacheKey(agentId, versionFilter)]?.conversationIds ?? EMPTY_IDS;
const makeSelectAgentConversations = makeSelectAgentConversationList;
function selectAgentConversationsEntry(state, agentId, versionFilter) {
  return state.conversationList.agentCaches[conversationListCacheKey(agentId, versionFilter)];
}
function selectAgentConversationsEntryForInstance(state, instanceId, versionFilter) {
  const mapKey = selectAgentIdFromInstance(instanceId)(state);
  if (!mapKey) return void 0;
  const agent = selectAgentById(state, mapKey);
  const canonicalAgentId = agent?.parentAgentId ?? agent?.id ?? mapKey;
  return selectAgentConversationsEntry(state, canonicalAgentId, versionFilter);
}
function findConversationRow(state, conversationId) {
  const fromList = state.conversationList.byConversationId[conversationId];
  if (fromList) return fromList;
  for (const scope of Object.values(state.conversationHistory.scopes)) {
    const row = scope.items.find((i) => i.conversationId === conversationId);
    if (row) return row;
  }
  return null;
}
export {
  findConversationRow,
  makeSelectAgentConversationList,
  makeSelectAgentConversations,
  selectAgentConversationIds,
  selectAgentConversationsCache,
  selectAgentConversationsEntry,
  selectAgentConversationsEntryForInstance,
  selectConversationIsPending,
  selectConversationListItemById,
  selectGlobalConversationIds,
  selectGlobalConversationList,
  selectGlobalListError,
  selectGlobalListHasMore,
  selectGlobalListIsFresh,
  selectGlobalListLastFetchedAt,
  selectGlobalListStatus
};
