import { isAspectRatioOptionSet } from "../../ui/aspect-ratio-options.js";
const PILL_MAX_OPTIONS = 4;
const PILL_MAX_LABEL = 12;
const SELECT_MAX_OPTIONS = 12;
function fitsPills(options) {
  return options.length > 0 && options.length <= PILL_MAX_OPTIONS && options.every((o) => o.length <= PILL_MAX_LABEL);
}
function choiceControlFor(options) {
  if (isAspectRatioOptionSet(options)) return "aspect-ratio";
  if (fitsPills(options)) return "pill-toggle";
  if (options.length > SELECT_MAX_OPTIONS) return "searchable";
  return "select";
}
function choiceComponentType(options) {
  return choiceControlFor(options) === "pill-toggle" ? "pill-toggle" : "select";
}
export {
  PILL_MAX_LABEL,
  PILL_MAX_OPTIONS,
  SELECT_MAX_OPTIONS,
  choiceComponentType,
  choiceControlFor,
  fitsPills
};
