import { createAsyncThunk } from "@reduxjs/toolkit";
import {
  getConversationSandboxBinding,
  getSurfaceSeedRef,
  getActiveSandboxBinding,
  resolveSandboxRefDetails,
  clearSandboxBindingCache
} from "../../../../compute/targets.js";
import { setConversationSandbox } from "../../conversation-list/conversation-row-actions.thunks.js";
import { selectConversationSandboxPersisted } from "../conversations/conversations.selectors.js";
import { setPreference, selectSandboxBySurface } from "../../../../host/prefs.js";
import { openSandboxGate } from "../../../../compute/targets.js";
const LOG = "[sandbox-gate]";
function toStoredRef(ref) {
  return {
    rowId: ref.rowId,
    proxyUrl: ref.proxyUrl,
    tier: ref.tier,
    kind: ref.kind,
    name: ref.name
  };
}
function clearSurfaceSeed(state, conversationId, dispatch) {
  const sourceFeature = state.conversations?.byConversationId?.[conversationId]?.sourceFeature;
  if (!sourceFeature) return;
  const bySurface = {
    ...selectSandboxBySurface(state)
  };
  if (!(sourceFeature in bySurface)) return;
  delete bySurface[sourceFeature];
  dispatch(
    setPreference({
      module: "coding",
      preference: "activeAgentSandboxBySurface",
      value: bySurface
    })
  );
}
const detachSandboxForConversation = createAsyncThunk(
  "sandbox/detachForConversation",
  async (conversationId, { getState, dispatch }) => {
    const state = getState();
    const binding = getConversationSandboxBinding(state, conversationId);
    const seed = getSurfaceSeedRef(state, conversationId);
    if (binding) {
      await dispatch(
        setConversationSandbox({ conversationId, ref: null })
      ).unwrap();
    }
    clearSurfaceSeed(state, conversationId, dispatch);
    const rowId = binding?.rowId ?? seed?.rowId;
    if (rowId) clearSandboxBindingCache(rowId);
  }
);
const promoteSurfaceSeedToConversation = createAsyncThunk(
  "sandbox/promoteSeed",
  async ({ conversationId, ref }, { dispatch }) => {
    await dispatch(
      setConversationSandbox({ conversationId, ref: toStoredRef(ref) })
    ).unwrap();
  }
);
const ensureSandboxOrDecide = createAsyncThunk(
  "sandbox/ensureOrDecide",
  async ({ conversationId }, { getState, dispatch }) => {
    const binding = getConversationSandboxBinding(getState(), conversationId);
    if (!binding) {
      const seed = getSurfaceSeedRef(getState(), conversationId);
      if (!seed) return "proceed";
      if (await getActiveSandboxBinding(getState, conversationId)) {
        await dispatch(
          promoteSurfaceSeedToConversation({ conversationId, ref: seed })
        ).unwrap();
        return "proceed";
      }
      console.warn(
        `${LOG} surface default box ${seed.rowId} (${seed.name ?? "unnamed"}) could not be resolved \u2014 it is stopped, expired, or gone. This conversation has never been bound to a sandbox, so the send proceeds WITHOUT one (no gate). Attach a live box from the Sandbox panel to bind it.`
      );
      return "proceed";
    }
    let healed = binding;
    if (!binding.proxyUrl && binding.kind !== "local-pc") {
      const details = await resolveSandboxRefDetails(binding.rowId);
      if (details) {
        healed = { ...binding, ...details };
        await dispatch(
          setConversationSandbox({
            conversationId,
            ref: toStoredRef(healed)
          })
        ).unwrap();
      }
    }
    if (!selectConversationSandboxPersisted(conversationId)(getState())) {
      try {
        await dispatch(
          setConversationSandbox({ conversationId, ref: toStoredRef(healed) })
        ).unwrap();
      } catch (err) {
        console.error(
          `${LOG} \u274C failed to persist the compute-target binding for conversation ${conversationId} to cx_conversation (sandbox_instance_id / app_instance_id). The server may not see this box as bound.`,
          err
        );
      }
    }
    if (await getActiveSandboxBinding(getState, conversationId)) return "proceed";
    const choice = await openSandboxGate({ conversationId });
    if (choice === "detach") {
      await dispatch(detachSandboxForConversation(conversationId)).unwrap();
      return "proceed";
    }
    if (choice === "attach") {
      if (await getActiveSandboxBinding(getState, conversationId)) {
        const next = getConversationSandboxBinding(getState(), conversationId);
        if (!next) {
          const seed = getSurfaceSeedRef(getState(), conversationId);
          if (seed) {
            await dispatch(
              promoteSurfaceSeedToConversation({ conversationId, ref: seed })
            ).unwrap();
          }
        }
        return "proceed";
      }
      return "blocked";
    }
    return "blocked";
  }
);
export {
  detachSandboxForConversation,
  ensureSandboxOrDecide,
  promoteSurfaceSeedToConversation
};
