import {
  CHAT_DEFAULT_MODEL_KNOB,
  modelClassKnobFor,
  modelClassPinOf,
  resolvePreferredModelChoice
} from "@ai-matrx/agents/models";
import { supabase } from "../../host/db.js";
import { ensureEffectiveKnob } from "../../host/prefs.js";
import { getActiveOrgId } from "../../host/org.js";
import { getUserId } from "../../host/identity.js";
async function resolvePreferredChatModel() {
  try {
    return await resolvePreferredModelChoice(
      {
        client: () => supabase,
        resolveKnob: (fullKey) => ensureEffectiveKnob(getActiveOrgId(), getUserId(), fullKey),
        classKnobFor: modelClassKnobFor,
        classPinOf: (value) => modelClassPinOf(value) ?? null
      },
      CHAT_DEFAULT_MODEL_KNOB,
      "preferredChatModel"
    );
  } catch (error) {
    console.error(
      `[preferredChatModel] ${CHAT_DEFAULT_MODEL_KNOB} could not be resolved \u2014 the Holder's own model answers this run:`,
      error
    );
    return null;
  }
}
export {
  resolvePreferredChatModel
};
