const ASSISTANT_BLOCK_TAGS = [
  "thinking",
  "think",
  "reasoning",
  "info",
  "task",
  "database",
  "private",
  "plan",
  "event",
  "tool",
  "questionnaire",
  "flashcards",
  "cooking_recipe",
  "timeline",
  "progress_tracker",
  "troubleshooting",
  "resources",
  "research",
  "decision",
  "artifact",
  "option"
];
const TAG_RE = new RegExp(`<(/?(?:${ASSISTANT_BLOCK_TAGS.join("|")}))(?=[\\s>/])`, "gi");
const CODE_RE = /(```[\s\S]*?(?:```|$)|`[^`\n]*`)/g;
function literalUserText(text) {
  return text.split(CODE_RE).map((part, i) => i % 2 === 1 ? part : part.replace(TAG_RE, "&lt;$1")).join("");
}
export {
  literalUserText
};
