import {
  SAMPLE_RATE_HZ,
  TURN_PREFIX_PADDING_MS,
  TURN_SILENCE_MS
} from "../constants.js";
function buildSessionUpdate(payload) {
  const tools = payload.tools.map(
    (t) => t.execution === "builtin" ? { type: t.name } : {
      type: "function",
      name: t.name,
      description: t.description,
      parameters: t.parameters
    }
  );
  return JSON.stringify({
    type: "session.update",
    session: {
      voice: payload.voiceId,
      instructions: payload.instructions,
      // THE TURN IS THE SPEAKER'S TO END. `silence_duration_ms` is always sent
      // — the provider default is short enough to cut a person off mid-thought,
      // which is exactly what a slow, considered answer sounds like to VAD.
      turn_detection: {
        type: "server_vad",
        silence_duration_ms: payload.turnSilenceMs ?? TURN_SILENCE_MS,
        prefix_padding_ms: payload.turnPrefixPaddingMs ?? TURN_PREFIX_PADDING_MS,
        ...payload.createResponseOnTurn === false ? { create_response: false } : {}
      },
      tools,
      input_audio_transcription: { model: "grok-2-audio" },
      audio: {
        input: { format: { type: "audio/pcm", rate: SAMPLE_RATE_HZ } },
        output: { format: { type: "audio/pcm", rate: SAMPLE_RATE_HZ } }
      }
    }
  });
}
function buildAudioAppend(b64Pcm) {
  return JSON.stringify({
    type: "input_audio_buffer.append",
    audio: b64Pcm
  });
}
function buildResponseCancel() {
  return JSON.stringify({ type: "response.cancel" });
}
function buildFunctionCallOutput(callId, output) {
  return JSON.stringify({
    type: "conversation.item.create",
    item: {
      type: "function_call_output",
      call_id: callId,
      output
    }
  });
}
function buildResponseCreate(instructions) {
  if (instructions && instructions.trim().length > 0) {
    return JSON.stringify({
      type: "response.create",
      response: { instructions }
    });
  }
  return JSON.stringify({ type: "response.create" });
}
function buildConversationTextItem(id, role, text) {
  return JSON.stringify({
    type: "conversation.item.create",
    item: {
      id,
      type: "message",
      role,
      content: [{ type: "input_text", text }]
    }
  });
}
function buildConversationItemDelete(itemId) {
  return JSON.stringify({ type: "conversation.item.delete", item_id: itemId });
}
export {
  buildAudioAppend,
  buildConversationItemDelete,
  buildConversationTextItem,
  buildFunctionCallOutput,
  buildResponseCancel,
  buildResponseCreate,
  buildSessionUpdate
};
