"use client";
import { fileUrls, useFileUpload } from "@ai-matrx/rich-content/host/app-bindings";
import { toast } from "@ai-matrx/rich-content/host/toast";
function imageAltOf(fileName) {
  return fileName.replace(/\.[^.]+$/, "").replace(/[[\]]/g, "") || "image";
}
function createMarkdownImageUpload(upload, urls) {
  return async (file) => {
    try {
      const uploaded = await upload({ kind: "file", file }, { folderPath: "Editor images" });
      return `![${imageAltOf(file.name)}](${urls(uploaded.fileId).inline})`;
    } catch (error) {
      toast.error(`The image did not upload: ${error instanceof Error ? error.message : String(error)}`);
      return null;
    }
  };
}
function useMarkdownImageUpload() {
  const { upload } = useFileUpload();
  return createMarkdownImageUpload(upload, fileUrls);
}
function imageFilesOf(data) {
  return Array.from(data?.files ?? []).filter((file) => file.type.startsWith("image/"));
}
async function insertUploadedImages(el, files, at, uploadImage) {
  let from = at.from;
  let to = at.to;
  for (const file of files) {
    const markdown = await uploadImage(file);
    if (!markdown || !el.isConnected) continue;
    const text = el.value;
    const start = Math.min(from, text.length);
    const end = Math.min(Math.max(to, start), text.length);
    const before = text.slice(0, start);
    const lead = before === "" || /\s$/.test(before) ? "" : " ";
    const insert = `${lead}${markdown}`;
    el.focus({ preventScroll: true });
    el.setSelectionRange(start, end);
    let done = false;
    try {
      done = typeof document.execCommand === "function" && document.execCommand("insertText", false, insert);
    } catch {
      done = false;
    }
    if (!done || el.value === text) {
      el.setRangeText(insert, start, end, "end");
      el.dispatchEvent(new Event("input", { bubbles: true }));
    }
    from = start + insert.length;
    to = from;
    el.setSelectionRange(from, from);
  }
}
export {
  createMarkdownImageUpload,
  imageAltOf,
  imageFilesOf,
  insertUploadedImages,
  useMarkdownImageUpload
};
