import { outputTypeLabel } from "./output-selection.js";
const OUTPUT_TYPE_MODALITY = {
  text: "text",
  image: "image",
  audio: "audio",
  voice: "audio",
  music: "audio",
  video: "video"
};
function agentOutputFilterSpec(types) {
  const modalities = [];
  const labels = [];
  for (const type of types) {
    const modality = OUTPUT_TYPE_MODALITY[type];
    if (!modality) continue;
    labels.push(outputTypeLabel(type));
    if (!modalities.includes(modality)) modalities.push(modality);
  }
  if (modalities.length === 0) return null;
  if (modalities.length === 1 && modalities[0] === "text") return null;
  return { label: `Makes: ${labels.join(", ")}`, modalities };
}
function modelOutputModalities(capabilities) {
  if (!capabilities || typeof capabilities !== "object") return null;
  const output = capabilities.output;
  if (!Array.isArray(output)) return null;
  const list = output.filter((value) => typeof value === "string");
  return list.length > 0 ? list : null;
}
function modelMakesAny(outputs, wanted) {
  if (!outputs) return true;
  return wanted.some(
    // A decision model answers typed questions instead of writing; it serves
    // a text ask (the same rule the model picker applies to agent models).
    (want) => outputs.includes(want) || want === "text" && outputs.includes("decision")
  );
}
export {
  OUTPUT_TYPE_MODALITY,
  agentOutputFilterSpec,
  modelMakesAny,
  modelOutputModalities
};
