import {
  buildConversationItemDelete,
  buildConversationTextItem,
  buildResponseCreate
} from "../transport/clientEvents.js";
import {
  transcriptTextFromEvent
} from "../transport/serverEvents.js";
import {
  buildDeliveryCueText,
  buildMirrorCueText,
  buildNarrationCueText
} from "./relayProtocol.js";
import {
  createVoiceExchangeLog,
  formatVoiceExchange
} from "./sideChannel.js";
const RELAY_CONTEXT_WINDOW_ITEMS = 8;
function createVoiceRelayController(options) {
  const windowItems = options.windowItems ?? RELAY_CONTEXT_WINDOW_ITEMS;
  const log = options.log ?? ((kind, code, detail) => {
    const line = `[voice-relay] ${code}: ${detail}`;
    if (kind === "warn") console.warn(line);
  });
  let handle = null;
  let detachEvents = null;
  let disposed = false;
  const exchangeLog = createVoiceExchangeLog();
  function notifyExchangeChanged() {
    options.onExchangeUpdated?.(formatVoiceExchange(exchangeLog.peek()));
  }
  let awaitingBrain = false;
  let expectedResponses = 0;
  const cueItemIds = [];
  let cueSeq = 1;
  function handleEvent(event) {
    if (disposed) return;
    switch (event.type) {
      case "conversation.item.input_audio_transcription.completed": {
        const transcript = transcriptTextFromEvent(event, [
          "transcript",
          "text",
          "delta"
        ]).trim();
        if (!transcript) {
          log(
            "warn",
            "utterance.empty",
            "a completed transcription carried no readable text in any known wire field \u2014 the user spoke and the brain heard nothing. Check the xAI event shape."
          );
          return;
        }
        awaitingBrain = true;
        log("info", "utterance.captured", transcript.slice(0, 120));
        options.onUserUtterance(transcript);
        return;
      }
      // The Communicator's own spoken words — recorded so the brain sees
      // exactly what was said aloud on its behalf (ruling 6). Both wire
      // spellings of the transcript-done event are aliases.
      case "response.output_audio_transcript.done":
      case "response.audio_transcript.done": {
        if (event.transcript?.trim()) {
          exchangeLog.record("communicator", event.transcript);
          notifyExchangeChanged();
        }
        return;
      }
      case "response.created": {
        if (expectedResponses > 0) {
          expectedResponses -= 1;
          return;
        }
        if (awaitingBrain) {
          log(
            "warn",
            "unsolicited-response.cancelled",
            "voice model started a response while awaiting the primary agent \u2014 create_response gate breached; cancelling. Investigate session config."
          );
          handle?.cancelResponse();
          options.onUnsolicitedResponse?.();
        }
        return;
      }
      default:
        return;
    }
  }
  function sendCue(text, role = "user") {
    if (!handle) {
      log("warn", "cue.dropped", "no live session handle \u2014 cue not sent");
      return;
    }
    const itemId = `relay_cue_${cueSeq++}`;
    handle.sendRaw(buildConversationTextItem(itemId, role, text));
    cueItemIds.push(itemId);
    while (cueItemIds.length > windowItems) {
      const oldest = cueItemIds.shift();
      if (oldest) {
        try {
          handle.sendRaw(buildConversationItemDelete(oldest));
        } catch {
        }
      }
    }
    expectedResponses += 1;
    handle.sendRaw(buildResponseCreate());
  }
  return {
    binding: {
      attach(sessionHandle) {
        handle = sessionHandle;
        detachEvents = sessionHandle.onEvent(handleEvent);
        log("info", "attached", "relay attached to realtime session");
        return () => {
          detachEvents?.();
          detachEvents = null;
          handle = null;
          awaitingBrain = false;
          expectedResponses = 0;
          cueItemIds.length = 0;
          log("info", "detached", "relay detached from realtime session");
        };
      }
    },
    speakDelivery(primaryAgentResponse, opts) {
      awaitingBrain = false;
      sendCue(buildDeliveryCueText(primaryAgentResponse, opts));
    },
    speakNarration(narration) {
      sendCue(buildNarrationCueText(narration));
    },
    speakMirror() {
      sendCue(buildMirrorCueText());
    },
    isAwaitingBrain() {
      return awaitingBrain;
    },
    markAwaitingBrain() {
      awaitingBrain = true;
    },
    clearAwaitingBrain() {
      awaitingBrain = false;
    },
    drainVoiceExchange() {
      const drained = exchangeLog.drain();
      if (drained.length > 0) notifyExchangeChanged();
      return drained;
    },
    recordSideChannelUserTurn(text) {
      exchangeLog.record("user", text);
      notifyExchangeChanged();
    },
    dispose() {
      disposed = true;
      detachEvents?.();
      detachEvents = null;
      handle = null;
    }
  };
}
export {
  RELAY_CONTEXT_WINDOW_ITEMS,
  createVoiceRelayController
};
