async function listSurfaceValues(surfaceName) {
  const { data, error } = await sb().schema("ui").from("ui_surface_value").select("*").is("deleted_at", null).eq("surface_name", surfaceName).order("sort_order", { ascending: true }).order("name", { ascending: true });
  if (error) throw error;
  const rows = (data ?? []).map(rowToSurfaceValue);
  const groups = getManifest(surfaceName)?.groups;
  if (!groups || groups.length === 0) return rows;
  const groupOrder = new Map(groups.map((g) => [g.key, g.sortOrder]));
  const rowGroup = new Map(
    (data ?? []).map((r) => [bindingKeyOfValueRow(r), r.group_key ?? "general"])
  );
  return rows.map((row, i) => ({ row, i })).sort((a, b) => {
    const ga = groupOrder.get(rowGroup.get(a.row.name) ?? "general") ?? 850;
    const gb = groupOrder.get(rowGroup.get(b.row.name) ?? "general") ?? 850;
    return ga !== gb ? ga - gb : a.i - b.i;
  }).map((x) => x.row);
}
