import { selectHostConversation } from "../host-conversations/host-conversations.selectors.js";
import { loadHostHistory } from "../host-conversations/host-conversation.thunks.js";
import { createAsyncThunk } from "@reduxjs/toolkit";
import { prependMessages, setOlderLoading } from "../messages/messages.slice.js";
import { mergeToolCalls } from "../observability/observability.slice.js";
import {
  fetchConversationBundle,
  extractBundleToolCalls,
  messageRowToRecord,
  toolCallRowToRecord
} from "./conversation-bundle.js";
const loadOlderMessages = createAsyncThunk(
  "conversations/loadOlder",
  async ({ conversationId, pageSize = 50 }, { dispatch, getState, rejectWithValue }) => {
    if (selectHostConversation(conversationId)(getState())) {
      const before = getState().messages.byConversationId[conversationId]?.orderedIds.length ?? 0;
      await loadHostHistory(dispatch, getState, conversationId, { older: true });
      const after = getState().messages.byConversationId[conversationId];
      return {
        conversationId,
        prependedCount: Math.max(0, (after?.orderedIds.length ?? 0) - before),
        hasMoreOlder: after?.hasMoreOlder ?? false
      };
    }
    const entry = getState().messages.byConversationId[conversationId];
    if (!entry) {
      return rejectWithValue({ reason: "no-entry" });
    }
    if (entry.isLoadingOlder) {
      return rejectWithValue({ reason: "already-loading" });
    }
    if (!entry.hasMoreOlder) {
      return rejectWithValue({ reason: "no-more" });
    }
    if (entry.oldestPosition == null) {
      return rejectWithValue({ reason: "no-cursor" });
    }
    const cursor = entry.oldestPosition;
    dispatch(setOlderLoading({ conversationId, loading: true }));
    try {
      const bundle = await fetchConversationBundle(conversationId, {
        messageLimit: pageSize,
        beforePosition: cursor,
        skipObservabilityFallback: true
      });
      const messageRecords = bundle.messages.map(messageRowToRecord);
      const toolCallRecords = extractBundleToolCalls(bundle).map(toolCallRowToRecord);
      const pagination = bundle.pagination ?? {
        limit: pageSize,
        returned_count: messageRecords.length,
        oldest_position: messageRecords[0]?.position ?? cursor,
        has_more: false
      };
      if (toolCallRecords.length > 0) {
        dispatch(mergeToolCalls({ toolCalls: toolCallRecords }));
      }
      dispatch(
        prependMessages({
          conversationId,
          messages: messageRecords,
          pagination: {
            oldestPosition: pagination.oldest_position,
            hasMoreOlder: pagination.has_more
          }
        })
      );
      return {
        conversationId,
        prependedCount: messageRecords.length,
        hasMoreOlder: pagination.has_more
      };
    } catch (err) {
      dispatch(setOlderLoading({ conversationId, loading: false }));
      console.error("[loadOlderMessages] failed:", err);
      throw err;
    }
  }
);
export {
  loadOlderMessages
};
