import { createClient } from "../../host/db.js";
import { tryWriteOne } from "@ai-matrx/data/db";
import { getClaimsUser } from "../../host/db.js";
import {
  presentOrganizationRefusal,
  organizationRefusalMessage
} from "../../host/org.js";
import {
  PERSISTENCE_MESSAGE_SOURCE_ASSISTANT,
  PERSISTENCE_MESSAGE_SOURCE_USER,
  PERSISTENCE_PROVIDER,
  PERSISTENCE_REGION,
  PERSISTENCE_SOURCE_APP,
  PERSISTENCE_SOURCE_FEATURE
} from "../constants.js";
import { ensureOrgId } from "../../host/org.js";
function toolNames(tools) {
  return tools.map((t) => t.name);
}
function clientOrThrow() {
  return createClient();
}
async function ensureConversation(conversationId, opts) {
  const supabase = clientOrThrow();
  const {
    data: { user },
    error: userErr
  } = await getClaimsUser(supabase);
  if (userErr || !user) {
    return {
      ok: false,
      error: userErr?.message ?? "Not authenticated."
    };
  }
  const metadataVoice = {
    provider: PERSISTENCE_PROVIDER,
    // Model slug — xAI Realtime models are NOT in the `ai_model` table, so we
    // record the identifier here instead of in `cx_conversation.last_model_id`
    // (which is a UUID FK to ai_model.id and would 22P02 with a slug).
    model: opts.model ?? null,
    voice_id: opts.voiceId,
    tools_enabled: toolNames(opts.tools),
    region: PERSISTENCE_REGION,
    preset: opts.preset,
    total_turns: 0,
    total_interruptions: 0
  };
  let organizationId;
  try {
    organizationId = await ensureOrgId(void 0);
  } catch (err) {
    if (presentOrganizationRefusal(err, {
      subject: "This voice conversation",
      act: "saved"
    })) {
      return { ok: false, error: organizationRefusalMessage({
        subject: "This voice conversation",
        act: "saved"
      }) };
    }
    throw err;
  }
  const insert = {
    id: conversationId,
    // Canonical ownership column (replaces the dropped `user_id`). The
    // `_stamp_actor` trigger also defaults this from auth.uid() on insert.
    created_by: user.id,
    // Root entity (no org-inherit trigger) — org is NOT NULL; resolve it.
    organization_id: organizationId,
    is_ephemeral: false,
    status: "active",
    source_app: PERSISTENCE_SOURCE_APP,
    source_feature: PERSISTENCE_SOURCE_FEATURE,
    system_instruction: opts.instructions,
    // Intentionally NOT setting last_model_id — it's a UUID FK to ai_model.id,
    // and the xAI Realtime model isn't registered there. The model slug lives
    // in metadata.voice.model above.
    metadata: { voice: metadataVoice },
    overrides: { tools: opts.tools },
    message_count: 0
  };
  const { error } = await supabase.schema("chat").from("conversation").upsert(insert, { onConflict: "id", ignoreDuplicates: true });
  if (error) {
    console.error(
      "[voiceTranscriptWriter] ensureConversation error:",
      error.message
    );
    return { ok: false, error: error.message };
  }
  return { ok: true };
}
async function persistTurns(opts) {
  if (opts.turns.length === 0) return { ok: true, persistedTurnIds: [] };
  const supabase = clientOrThrow();
  let orgId;
  try {
    orgId = await ensureOrgId(void 0);
  } catch (err) {
    if (presentOrganizationRefusal(err, {
      subject: "This transcript",
      act: "saved"
    })) {
      return { ok: false, error: organizationRefusalMessage({
        subject: "This transcript",
        act: "saved"
      }) };
    }
    throw err;
  }
  const rows = opts.turns.map((turn, idx) => {
    const voiceMeta = {
      turn_id: turn.id,
      started_at_ms: turn.started_at_ms,
      ended_at_ms: turn.ended_at_ms ?? null,
      was_interrupted: turn.status === "interrupted"
    };
    if (turn.item_id) voiceMeta.item_id = turn.item_id;
    if (turn.response_id) voiceMeta.response_id = turn.response_id;
    if (turn.audio_duration_ms !== void 0) {
      voiceMeta.audio_duration_ms = turn.audio_duration_ms;
    }
    if (turn.speech_ttfb_ms !== void 0) {
      voiceMeta.speech_ttfb_ms = turn.speech_ttfb_ms;
    }
    return {
      conversation_id: opts.conversationId,
      organization_id: orgId,
      role: turn.role,
      position: opts.startPosition + idx,
      // `cx_message.source` only allows 'user' | 'agent_template' | 'system'
      // (CHECK constraint `cx_message_source_check`). Per-turn voice data lives
      // in the dedicated `voice` column below; conversation-level voice
      // provenance (provider, model, …) lives in `cx_conversation.metadata.voice`
      // — written by finalizeConversation. See constants.ts.
      source: turn.role === "user" ? PERSISTENCE_MESSAGE_SOURCE_USER : PERSISTENCE_MESSAGE_SOURCE_ASSISTANT,
      content: [
        { type: "text", text: turn.text || "" }
      ],
      // Voice-turn metadata now lives in the dedicated top-level `voice` jsonb
      // column on cx_message (was previously nested under `metadata.voice`).
      voice: voiceMeta,
      // `cx_message.status` is a strictly enumerated CHECK constraint
      // (`cx_message_status_check`): only 'active' | 'condensed' | 'summary'
      // | 'deleted' | 'pending' | 'abandoned' | 'failed' are allowed — verified
      // against the live DB. The canonical chat writer (cx-chat.ts:createCxMessage)
      // omits status entirely and relies on the column default of 'active';
      // we set it explicitly so the mapping intent is visible at the callsite.
      // Production usage (per `SELECT status, count(*) FROM cx_message`):
      //   • normal completed turn  → 'active'   (the default — same as text chat)
      //   • user-interrupted turn  → 'abandoned' (closest enum match — the
      //     turn was cut off mid-flight by the user barging in over the
      //     assistant; analytics also have `metadata.voice.was_interrupted`)
      // Do NOT pass voice-specific strings like 'completed' or 'interrupted'
      // here — they violate the CHECK constraint and the whole insert
      // (entire batch of turns) is rejected with 23514.
      status: turn.status === "interrupted" ? "abandoned" : "active",
      // Interrupted assistant turns must NOT poison future model context.
      is_visible_to_model: turn.role === "assistant" && turn.status === "interrupted" ? false : true,
      is_visible_to_user: true
    };
  });
  const { error } = await supabase.schema("chat").from("message").insert(rows);
  if (error) {
    console.error("[voiceTranscriptWriter] persistTurns error:", error.message);
    return { ok: false, error: error.message };
  }
  return { ok: true, persistedTurnIds: opts.turns.map((t) => t.id) };
}
async function finalizeConversation(opts) {
  const supabase = clientOrThrow();
  const voiceMeta = {
    provider: PERSISTENCE_PROVIDER,
    model: opts.model ?? null,
    voice_id: opts.voiceId,
    tools_enabled: toolNames(opts.tools),
    region: PERSISTENCE_REGION,
    preset: opts.preset,
    total_turns: opts.totalTurns,
    total_interruptions: opts.totalInterruptions,
    latency_p50_ms: opts.latency.p50_ms,
    latency_p95_ms: opts.latency.p95_ms,
    latency_sample_count: opts.latency.count
  };
  const { error } = await tryWriteOne(
    supabase.schema("chat").from("conversation").update({
      message_count: opts.totalTurns,
      metadata: { voice: voiceMeta }
    }).eq("id", opts.conversationId).select("id"),
    { action: "save", noun: "conversation" }
  );
  if (error) {
    console.error(
      "[voiceTranscriptWriter] finalizeConversation error:",
      error.message
    );
    return { ok: false, error: error.message };
  }
  return { ok: true };
}
export {
  ensureConversation,
  finalizeConversation,
  persistTurns
};
