import { apiPost } from "../../host/server/typed-client.js";
const EXECUTE_PATH = "/ai/tools/execute";
function createRealtimeToolService() {
  return {
    async execute(req) {
      try {
        const { context, ...rest } = req;
        const body = {
          ...rest,
          ...context?.organization_id ? { organization_id: context.organization_id } : {},
          ...context?.project_id ? { project_id: context.project_id } : {},
          ...context?.task_id ? { task_id: context.task_id } : {},
          ...context?.scope_ids ? { scope_ids: context.scope_ids } : {}
        };
        const { data } = await apiPost(EXECUTE_PATH, body);
        return { ok: data.ok, output: data.output };
      } catch (err) {
        const message = err instanceof Error ? err.message : "tool service request failed";
        return { ok: false, output: `Tool service error: ${message}` };
      }
    }
  };
}
const realtimeToolService = createRealtimeToolService();
export {
  createRealtimeToolService,
  realtimeToolService
};
