const MAX_TURN_CHARS = 1500;
const MAX_TURNS = 40;
function createVoiceExchangeLog() {
  const turns = [];
  return {
    record(speaker, text) {
      const trimmed = text.trim();
      if (!trimmed) return;
      turns.push({
        speaker,
        text: trimmed.length > MAX_TURN_CHARS ? `${trimmed.slice(0, MAX_TURN_CHARS)}\u2026` : trimmed
      });
      if (turns.length > MAX_TURNS) {
        console.warn(
          `[voice-relay] voice_exchange log exceeded ${MAX_TURNS} turns before a brain send \u2014 dropping the oldest. A brain turn should have happened by now.`
        );
        turns.shift();
      }
    },
    drain() {
      return turns.splice(0, turns.length);
    },
    peek() {
      return turns.map((t) => ({ ...t }));
    },
    size() {
      return turns.length;
    }
  };
}
function escapeXml(text) {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
const VOICE_EXCHANGE_INLINE_BUDGET_CHARS = 4800;
function formatVoiceExchange(turns) {
  if (turns.length === 0) return "";
  const header = `<voice_exchange note="A voice agent is speaking your responses to the user and asking your questions on your behalf. These are the spoken turns since your last message \u2014 for your context only; the user's actual reply is the message itself.">`;
  const footer = "</voice_exchange>";
  const lines = turns.map(
    (t) => `  <${t.speaker}>${escapeXml(t.text)}</${t.speaker}>`
  );
  const budget = VOICE_EXCHANGE_INLINE_BUDGET_CHARS - header.length - footer.length - 64;
  const kept = [];
  let used = 0;
  for (let i = lines.length - 1; i >= 0; i--) {
    const cost = lines[i].length + 1;
    if (used + cost > budget) break;
    kept.unshift(lines[i]);
    used += cost;
  }
  const dropped = lines.length - kept.length;
  const body = (dropped > 0 ? `  <note>${dropped} earlier spoken turns omitted</note>
` : "") + kept.join("\n");
  return `${header}
${body}
${footer}`;
}
function composeBrainMessage(exchangeTurns, userUtterance) {
  const block = formatVoiceExchange(exchangeTurns);
  return block ? `${block}

${userUtterance}` : userUtterance;
}
export {
  VOICE_EXCHANGE_INLINE_BUDGET_CHARS,
  composeBrainMessage,
  createVoiceExchangeLog,
  formatVoiceExchange
};
