"use client";
import { useCallback, useEffect, useMemo } from "react";
import { useAppDispatch, useAppSelector } from "../../store/hooks.js";
import {
  fetchAvailability,
  fetchCatalog,
  discoverServerTools,
  selectMcpCatalog,
  selectMcpCatalogStatus,
  selectMcpServerById,
  selectMcpServerDiscovery,
  selectMcpServerTools,
  selectAllDiscoveredMcpTools,
  selectMcpDiscoveries,
  selectMcpAvailabilityForOrganization,
  selectMcpAvailabilityStatusForOrganization
} from "../redux/mcp/mcp.slice.js";
import {
  deriveMcpConnectionState
} from "../connectors/connection-state.js";
import {
  normalizeAttachable
} from "../connectors/attachable-resources.js";
import { mcpConnectionRouteFor } from "./mcp-connection-route.js";
import { invokeMcpServerTool } from "../services/mcp-connections.service.js";
import { useGitHubConnection } from "../../host/ui-slots.js";
import { selectOrganizationId } from "../../host/org.js";
const EMPTY_MCP_TOOLS = [];
function useMcpCatalog() {
  const dispatch = useAppDispatch();
  const catalog = useAppSelector(selectMcpCatalog);
  const status = useAppSelector(selectMcpCatalogStatus);
  const organizationId = useAppSelector(selectOrganizationId);
  const github = useGitHubConnection();
  const githubStatus = github.loading ? void 0 : github.inventory.connection?.status ?? null;
  useEffect(() => {
    if (status === "idle") {
      dispatch(fetchCatalog());
    }
  }, [dispatch, status]);
  const availability = useAppSelector(
    (state) => selectMcpAvailabilityForOrganization(state, organizationId)
  );
  const availabilityStatus = useAppSelector(
    (state) => selectMcpAvailabilityStatusForOrganization(state, organizationId)
  );
  useEffect(() => {
    if (organizationId && availabilityStatus === "idle") {
      dispatch(fetchAvailability({ organizationId }));
    }
  }, [dispatch, organizationId, availabilityStatus]);
  const serverStates = useMemo(
    () => catalog.map((entry) => ({
      entry,
      truth: deriveMcpConnectionState(entry, {
        availability: availability[entry.slug] ?? null,
        hasFirstPartyPath: mcpConnectionRouteFor(entry) === "github",
        firstPartyStatus: mcpConnectionRouteFor(entry) === "github" ? githubStatus : void 0
      }),
      toolCount: availability[entry.slug]?.tool_count ?? null,
      // What this server lets a person CHOOSE from, in the server's own
      // vocabulary. Empty for a pure MCP connection — which is precisely
      // the difference the chips have to make visible.
      attachable: normalizeAttachable(availability[entry.slug]?.attachable)
    })),
    [catalog, availability, githubStatus]
  );
  const connectedServers = useMemo(
    () => serverStates.filter((s) => s.truth.state === "connected").map((s) => s.entry),
    [serverStates]
  );
  const reauthServers = useMemo(
    () => serverStates.filter((s) => s.truth.state === "needs_reauth"),
    [serverStates]
  );
  const refreshAvailability = useCallback(
    (slugs) => {
      if (organizationId) {
        dispatch(fetchAvailability({ organizationId, slugs }));
      }
    },
    [dispatch, organizationId]
  );
  return {
    catalog,
    connectedServers,
    serverStates,
    reauthServers,
    availabilityStatus,
    firstPartyLoading: github.loading,
    refreshAvailability,
    status
  };
}
function useMcpServerTools(serverId) {
  const dispatch = useAppDispatch();
  const server = useAppSelector(
    (state) => serverId ? selectMcpServerById(state, serverId) : null
  );
  const discovery = useAppSelector(
    (state) => serverId ? selectMcpServerDiscovery(state, serverId) : null
  );
  const tools = useAppSelector(
    (state) => serverId ? selectMcpServerTools(state, serverId) : EMPTY_MCP_TOOLS
  );
  const isConnected = server?.connectionStatus === "connected";
  const discoveryStatus = discovery?.status ?? "idle";
  useEffect(() => {
    if (serverId && isConnected && discoveryStatus === "idle") {
      dispatch(discoverServerTools(serverId));
    }
  }, [dispatch, serverId, isConnected, discoveryStatus]);
  const refresh = useCallback(() => {
    if (serverId) {
      dispatch(discoverServerTools(serverId));
    }
  }, [dispatch, serverId]);
  const invokeTool = useCallback(
    async (toolName, args) => {
      if (!serverId) throw new Error("No server ID");
      return invokeMcpServerTool(serverId, toolName, args);
    },
    [serverId]
  );
  return {
    server,
    tools,
    discovery,
    isConnected,
    discoveryStatus,
    refresh,
    invokeTool
  };
}
function useMcpAllTools() {
  const allTools = useAppSelector(selectAllDiscoveredMcpTools);
  const discoveries = useAppSelector(selectMcpDiscoveries);
  const isLoading = useMemo(
    () => Object.values(discoveries).some((d) => d.status === "loading"),
    [discoveries]
  );
  const findTool = useCallback(
    (toolName) => allTools.find((t) => t.name === toolName) ?? null,
    [allTools]
  );
  const invokeByName = useCallback(
    async (toolName, args) => {
      const tool = allTools.find((t) => t.name === toolName);
      if (!tool) throw new Error(`MCP tool not found: ${toolName}`);
      return invokeMcpServerTool(tool.serverId, toolName, args);
    },
    [allTools]
  );
  return { allTools, isLoading, findTool, invokeByName };
}
function useDiscoverAgentMcpTools(serverIds) {
  const dispatch = useAppDispatch();
  const discoveries = useAppSelector(selectMcpDiscoveries);
  const catalog = useAppSelector(selectMcpCatalog);
  useEffect(() => {
    for (const serverId of serverIds) {
      const catalogEntry = catalog.find((e) => e.serverId === serverId);
      if (!catalogEntry || catalogEntry.connectionStatus !== "connected")
        continue;
      const existing = discoveries[serverId];
      if (!existing || existing.status === "idle") {
        dispatch(discoverServerTools(serverId));
      }
    }
  }, [dispatch, serverIds, catalog, discoveries]);
  const agentTools = useMemo(() => {
    const tools = [];
    for (const serverId of serverIds) {
      const discovery = discoveries[serverId];
      if (!discovery || discovery.status !== "succeeded") continue;
      const catalogEntry = catalog.find((e) => e.serverId === serverId);
      const serverName = catalogEntry?.name ?? serverId;
      for (const tool of discovery.tools) {
        tools.push({ ...tool, serverId, serverName });
      }
    }
    return tools;
  }, [serverIds, discoveries, catalog]);
  const isLoading = useMemo(
    () => serverIds.some((id) => {
      const d = discoveries[id];
      return d?.status === "loading";
    }),
    [serverIds, discoveries]
  );
  return { agentTools, isLoading };
}
function useMcpServerTruth(entry) {
  const organizationId = useAppSelector(selectOrganizationId);
  const availability = useAppSelector(
    (state) => selectMcpAvailabilityForOrganization(state, organizationId)
  );
  return useMemo(
    () => deriveMcpConnectionState(entry, {
      availability: availability[entry.slug] ?? null,
      hasFirstPartyPath: mcpConnectionRouteFor({
        slug: entry.slug,
        authStrategy: entry.authStrategy
      }) === "github",
      firstPartyStatus: void 0
    }),
    [
      availability,
      entry.slug,
      entry.authStrategy,
      entry.connectionStatus,
      entry.tokenExpiresAt,
      entry.serverStatus
    ]
  );
}
function useMcpServerToolCount(slug) {
  const organizationId = useAppSelector(selectOrganizationId);
  const availability = useAppSelector(
    (state) => selectMcpAvailabilityForOrganization(state, organizationId)
  );
  return availability[slug]?.tool_count ?? null;
}
export {
  useDiscoverAgentMcpTools,
  useMcpAllTools,
  useMcpCatalog,
  useMcpServerToolCount,
  useMcpServerTools,
  useMcpServerTruth
};
