import {
  destroyInstance,
  destroyInstancesForAgent
} from "./conversations.slice.js";
const destroyInstanceIfAllowed = (conversationId) => (dispatch, getState) => {
  if (getState().conversations.debugSessionActive) return;
  dispatch(destroyInstance(conversationId));
};
const destroyInstancesForAgentIfAllowed = (agentId) => (dispatch, getState) => {
  if (getState().conversations.debugSessionActive) return;
  dispatch(destroyInstancesForAgent(agentId));
};
const destroyInstanceIfAbandoned = (conversationId) => (dispatch, getState) => {
  const state = getState();
  if (state.chatRoute?.draftHandoff?.pinnedSourceConversationIds.includes(
    conversationId
  )) {
    return;
  }
  if (state.conversations.debugSessionActive) return;
  const messageCount = state.messages.byConversationId[conversationId]?.orderedIds?.length ?? 0;
  if (messageCount > 0) return;
  const input = state.instanceUserInput.byConversationId[conversationId];
  const hasComposerWork = Boolean(input?.text.length) || Boolean(input?.messageParts?.length) || input != null && input.submissionPhase !== "idle";
  if (hasComposerWork) return;
  const added = state.instanceUIState.byConversationId[conversationId]?.builderAdvancedSettings;
  const hasRunConfiguration = Boolean(added?.addedTools?.length) || Boolean(added?.addedMcpServers?.length) || Boolean(added?.addedSkills?.length) || Boolean(added?.removedTools?.length) || (added?.autoTools ?? null) !== null;
  if (hasRunConfiguration) return;
  const attachments = state.conversationAttachments?.byConversationId?.[conversationId];
  if (Boolean(attachments?.pending?.length) || Boolean(attachments?.rows?.length)) {
    return;
  }
  dispatch(destroyInstance(conversationId));
};
export {
  destroyInstanceIfAbandoned,
  destroyInstanceIfAllowed,
  destroyInstancesForAgentIfAllowed
};
