const LAUNCHING_CONVERSATION_WAIT_MS = 15e3;
const POLL_MS = 50;
async function awaitLaunchingConversation(getState, conversationId, timeoutMs = LAUNCHING_CONVERSATION_WAIT_MS) {
  const exists = () => getState().conversations.byConversationId[conversationId] !== void 0;
  if (exists()) return true;
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    await new Promise((resolve) => setTimeout(resolve, POLL_MS));
    if (exists()) return true;
  }
  return false;
}
export {
  LAUNCHING_CONVERSATION_WAIT_MS,
  awaitLaunchingConversation
};
