const UTTERANCE_QUEUE_MAX = 20;
function createUtteranceQueue(max = UTTERANCE_QUEUE_MAX) {
  const held = [];
  let dropped = 0;
  return {
    enqueue(text, atMs = Date.now()) {
      const trimmed = text.trim();
      if (trimmed.length === 0) return;
      if (held.length >= max) {
        dropped += 1;
        console.error(
          "[voice-relay] the utterance buffer is full \u2014 an utterance could not be held. The surface must tell the speaker that the conversation is not reaching the interviewer.",
          { max, droppedSoFar: dropped }
        );
        return;
      }
      held.push({ text: trimmed, atMs });
    },
    flush(deliver) {
      if (held.length === 0) return 0;
      const batch = held.splice(0, held.length);
      for (const utterance of batch) deliver(utterance);
      return batch.length;
    },
    size() {
      return held.length;
    },
    droppedCount() {
      return dropped;
    },
    clear() {
      held.length = 0;
    }
  };
}
export {
  UTTERANCE_QUEUE_MAX,
  createUtteranceQueue
};
