  const preserved = blocks.filter((b) => b.type !== "text");
  const textBlock = mergedTextBlock(currentContent, blocks);
  const firstTextIndex = blocks.findIndex((b) => b.type === "text");
  if (firstTextIndex === -1) {
    return [...preserved, textBlock];
  }
  const result = [];
  let textInserted = false;
