import { createAsyncThunk } from "@reduxjs/toolkit";
import { supabase } from "../../../../host/db.js";
import { operationFailed } from "@ai-matrx/kit/errors";
import { destroyInstance } from "../conversations/conversations.slice.js";
import { clearMessages } from "../messages/messages.slice.js";
import { clearForConversation as clearObservabilityForConversation } from "../observability/observability.slice.js";
import {
  removeConversation as removeFromConversationList,
  addToTrash
} from "../../conversation-list/conversation-list.slice.js";
import { removeConversationFromScopes } from "../../conversation-history/slice.js";
import { findConversationRow } from "../../conversation-list/conversation-list.selectors.js";
import { clearCacheBypass } from "./cache-bypass.slice.js";
import { invalidateConversationCache } from "./invalidate-conversation-cache.thunk.js";
const softDeleteConversation = createAsyncThunk(
  "conversations/softDelete",
  async ({ conversationId }, { dispatch, getState, rejectWithValue }) => {
    const snapshot = findConversationRow(getState(), conversationId);
    const { data, error } = await supabase.rpc("cx_soft_delete_conversation", {
      p_conversation_id: conversationId
    });
    if (error) {
      return rejectWithValue({
        message: operationFailed("delete this conversation", error).message
      });
    }
    const deleted = data === true;
    if (!deleted) {
      return rejectWithValue({
        message: operationFailed("delete this conversation").message
      });
    }
    void dispatch(invalidateConversationCache({ conversationId }));
    dispatch(clearCacheBypass(conversationId));
    if (snapshot) {
      dispatch(addToTrash({ ...snapshot, deletedAt: (/* @__PURE__ */ new Date()).toISOString() }));
    }
    dispatch(removeFromConversationList(conversationId));
    dispatch(removeConversationFromScopes({ conversationId }));
    dispatch(clearMessages(conversationId));
    dispatch(clearObservabilityForConversation(conversationId));
    dispatch(destroyInstance(conversationId));
    return { conversationId, deleted: true };
  }
);
export {
  softDeleteConversation
};
