"use client";
import { useChatHost } from "./react.js";
function useChatCanvasView() {
  return useChatHost().canvas.useView();
}
function useChatCanvasOpeners() {
  return useChatHost().canvas.useOpeners();
}
function useChatCanvasTab(tab) {
  return useChatHost().canvas.useTab(tab);
}
export {
  useChatCanvasOpeners,
  useChatCanvasTab,
  useChatCanvasView
};
