const SHOW_PARKED_ASK_EVENT = "matrx:show-parked-ask";
function showParkedAsk() {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new CustomEvent(SHOW_PARKED_ASK_EVENT));
  window.setTimeout(() => {
    document.querySelector("[data-parked-ask]")?.scrollIntoView({ behavior: "smooth", block: "center" });
  }, 120);
}
export {
  SHOW_PARKED_ASK_EVENT,
  showParkedAsk
};
