import { loadOlderMessages } from "../redux/execution-system/thunks/load-older-messages.thunk.js";
const PAGE_SIZE = 200;
const MAX_PAGES = 200;
async function loadFullConversationHistory(dispatch, getState, conversationId, onProgress) {
  const count = () => getState().messages.byConversationId[conversationId]?.orderedIds?.length ?? 0;
  for (let page = 0; page < MAX_PAGES; page++) {
    const entry = getState().messages.byConversationId[conversationId];
    if (!entry?.hasMoreOlder) {
      onProgress?.(count());
      return { complete: true, loaded: count() };
    }
    try {
      await dispatch(loadOlderMessages({ conversationId, pageSize: PAGE_SIZE })).unwrap();
    } catch (err) {
      const reason = err?.reason;
      if (reason === "no-more") return { complete: true, loaded: count() };
      console.error("[loadFullConversationHistory] a page of history failed", err);
      return { complete: false, loaded: count() };
    }
    onProgress?.(count());
  }
  return { complete: false, loaded: count() };
}
export {
  loadFullConversationHistory
};
