import { storedMandateKey } from "@ai-matrx/agents/mandates";
const SHORTCUT_STORAGE_CUTOVER = true;
const SHORTCUT_STORAGE_LABEL = SHORTCUT_STORAGE_CUTOVER ? "mandate.vw_shortcut" : "agent.shortcut";
const agentShortcutTable = (supabase) => supabase.schema("agent").from("shortcut");
const mandateShortcutTable = (supabase) => supabase.schema("mandate").from("vw_shortcut");
const shortcutTable = SHORTCUT_STORAGE_CUTOVER ? mandateShortcutTable : agentShortcutTable;
const agentContextMenuView = (supabase) => supabase.schema("agent").from("context_menu_view");
const mandateContextMenuView = (supabase) => supabase.schema("mandate").from("context_menu_view");
const contextMenuView = SHORTCUT_STORAGE_CUTOVER ? mandateContextMenuView : agentContextMenuView;
const AGENT_RPCS = {
  buildMenu: "agx_build_shortcut_menu",
  forContext: "agx_get_shortcuts_for_context",
  userShortcuts: "agx_get_user_shortcuts",
  duplicate: "agx_duplicate_shortcut",
  promoteToGlobal: "agx_promote_shortcut_to_global",
  create: "agx_create_shortcut",
  listNonGlobalForAdmin: "agx_list_non_global_shortcuts_for_admin"
};
const MANDATE_RPCS = {
  buildMenu: "agx_build_shortcut_menu_m",
  forContext: "agx_get_shortcuts_for_context_m",
  userShortcuts: "agx_get_user_shortcuts_m",
  duplicate: "agx_duplicate_shortcut_m",
  promoteToGlobal: "agx_promote_shortcut_to_global_m",
  create: "agx_create_shortcut_m",
  listNonGlobalForAdmin: "agx_list_non_global_shortcuts_for_admin_m"
};
const SHORTCUT_RPCS = SHORTCUT_STORAGE_CUTOVER ? MANDATE_RPCS : AGENT_RPCS;
function mandateIdOfShortcutRow(row) {
  if (!SHORTCUT_STORAGE_CUTOVER) return null;
  return row.mandate_id ?? null;
}
const SHORTCUT_WRITE_POLICIES_ON_TREATMENT = SHORTCUT_STORAGE_CUTOVER;
function writePoliciesOfShortcutRow(row) {
  if (!SHORTCUT_WRITE_POLICIES_ON_TREATMENT) return null;
  const raw = row.write_policies;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  return raw;
}
function mandateKeyOfShortcutRow(row) {
  if (!SHORTCUT_STORAGE_CUTOVER) return null;
  const key = row.mandate_key ?? null;
  return key ? storedMandateKey(key) : null;
}
async function fetchShortcutMandateKey(supabase, shortcutId) {
  const { data, error } = await supabase.schema("mandate").from("vw_shortcut").select("mandate_key").eq("id", shortcutId).maybeSingle();
  if (error) {
    throw new Error(
      `Could not read the mandate behind shortcut ${shortcutId}: ${error.message}`
    );
  }
  const key = data?.mandate_key;
  if (!key) {
    throw new Error(
      `Shortcut ${shortcutId} has no mandate behind it, so it cannot run. Every shortcut runs through its mandate; open it in the shortcut editor and save it to repair the record.`
    );
  }
  return storedMandateKey(key);
}
export {
  SHORTCUT_RPCS,
  SHORTCUT_STORAGE_CUTOVER,
  SHORTCUT_STORAGE_LABEL,
  SHORTCUT_WRITE_POLICIES_ON_TREATMENT,
  contextMenuView,
  fetchShortcutMandateKey,
  mandateIdOfShortcutRow,
  mandateKeyOfShortcutRow,
  shortcutTable,
  writePoliciesOfShortcutRow
};
