import { createSelector } from "@reduxjs/toolkit";
import { idMatchesQuery } from "@ai-matrx/kit/search-scoring";
import {
  defaultScopeState,
  isLiveConversationRow
} from "./types.js";
import {
  CONVERSATION_LANES,
  normalizeLanes
} from "./lanes.js";
import { selectStoredConversationLanes } from "../../../host/prefs.js";
import { readAgentName } from "../../identity/agent-identity.js";
const selectConversationHistory = (state) => state.conversationHistory;
const selectSourceFacets = (state) => state.conversationHistory.sourceFacets;
const selectLaneCounts = createSelector(
  [selectSourceFacets],
  (facets) => {
    const counts = Object.fromEntries(
      CONVERSATION_LANES.map((l) => [l, 0])
    );
    for (const f of facets) if (f.lane) counts[f.lane] += f.count;
    return counts;
  }
);
const selectStoredLanes = (state) => selectStoredConversationLanes(state);
const selectConversationLanes = createSelector(
  [selectStoredLanes],
  (stored) => normalizeLanes(stored)
);
const selectSourceFacetsStatus = (state) => state.conversationHistory.sourceFacetsStatus;
const selectSourceFacetsError = (state) => state.conversationHistory.sourceFacetsError;
const makeSelectConversationHistoryScope = (scopeId) => createSelector(selectConversationHistory, (history) => {
  return history.scopes[scopeId] ?? defaultScopeState;
});
const makeSelectConversationHistoryItems = (scopeId) => {
  const selectScope = makeSelectConversationHistoryScope(scopeId);
  return createSelector(selectScope, (scope) => {
    const inView = scope.items.filter(
      (item) => isLiveConversationRow(item.status)
    );
    const term = scope.searchTerm.trim().toLowerCase();
    if (!term) return inView;
    return inView.filter((item) => {
      const title = (item.title ?? "").toLowerCase();
      const desc = (item.description ?? "").toLowerCase();
      return title.includes(term) || desc.includes(term) || idMatchesQuery(item, term);
    });
  });
};
const DATE_LABELS = {
  today: "Today",
  yesterday: "Yesterday",
  thisWeek: "This week",
  lastWeek: "Last week",
  thisMonth: "This month",
  older: "Earlier"
};
const ORDERED_KEYS = [
  "today",
  "yesterday",
  "thisWeek",
  "lastWeek",
  "thisMonth",
  "older"
];
const DAY_MS = 864e5;
function startOfDay(d) {
  const out = new Date(d);
  out.setHours(0, 0, 0, 0);
  return out;
}
function bucketForDate(updatedAt, now) {
  if (!updatedAt) return "older";
  const t = +new Date(updatedAt);
  if (Number.isNaN(t)) return "older";
  const today = startOfDay(now);
  const ageMs = today.getTime() - t;
  if (ageMs < 0 || t >= today.getTime()) return "today";
  if (ageMs < DAY_MS) return "yesterday";
  if (ageMs < 7 * DAY_MS) return "thisWeek";
  if (ageMs < 14 * DAY_MS) return "lastWeek";
  if (ageMs < 31 * DAY_MS) return "thisMonth";
  return "older";
}
const makeSelectGroupedByDate = (scopeId) => {
  const selectItems = makeSelectConversationHistoryItems(scopeId);
  return createSelector(selectItems, (items) => {
    const now = /* @__PURE__ */ new Date();
    const buckets = /* @__PURE__ */ new Map();
    for (const item of items) {
      const key = bucketForDate(item.updatedAt, now);
      const arr = buckets.get(key);
      if (arr) arr.push(item);
      else buckets.set(key, [item]);
    }
    const result = [];
    for (const k of ORDERED_KEYS) {
      const items2 = buckets.get(k);
      if (items2 && items2.length > 0) {
        result.push({ key: k, label: DATE_LABELS[k], items: items2 });
      }
    }
    return result;
  });
};
const makeSelectGroupedByAgent = (scopeId) => {
  const selectItems = makeSelectConversationHistoryItems(scopeId);
  return createSelector(
    [selectItems, (state) => state],
    (items, state) => {
      const buckets = /* @__PURE__ */ new Map();
      for (const item of items) {
        const id = item.agentId ?? null;
        const arr = buckets.get(id);
        if (arr) arr.push(item);
        else buckets.set(id, [item]);
      }
      const result = [];
      for (const [agentId, agentItems] of buckets.entries()) {
        let label = "Unknown agent";
        if (agentId) {
          label = readAgentName(state, agentId) ?? agentId.slice(0, 8);
        }
        result.push({ agentId, label, items: agentItems });
      }
      result.sort(
        (a, b) => +new Date(b.items[0]?.updatedAt ?? 0) - +new Date(a.items[0]?.updatedAt ?? 0)
      );
      return result;
    }
  );
};
const makeSelectConversationHistoryStatus = (scopeId) => {
  const selectScope = makeSelectConversationHistoryScope(scopeId);
  return createSelector(selectScope, (scope) => ({
    status: scope.status,
    hasMore: scope.hasMore,
    error: scope.error,
    count: scope.items.length
  }));
};
export {
  makeSelectConversationHistoryItems,
  makeSelectConversationHistoryScope,
  makeSelectConversationHistoryStatus,
  makeSelectGroupedByAgent,
  makeSelectGroupedByDate,
  selectConversationLanes,
  selectLaneCounts,
  selectSourceFacets,
  selectSourceFacetsError,
  selectSourceFacetsStatus
};
