"use client";
import { toast } from "../../../../host/notify.js";
import { useAppDispatch, useAppStore } from "../../../../store/hooks.js";
import {
  addResource,
  removeResource,
  setResourcePreview,
  setResourceStatus
} from "../../../redux/execution-system/instance-resources/instance-resources.slice.js";
import { generateResourceId } from "../../../redux/execution-system/utils/ids.js";
import {
  RENDERED_ARTIFACT_BLOCK_TYPE,
  registerRenderedArtifactCapture,
  renderedArtifactRepresentationLabel
} from "../../../utils/renderedArtifactContext.js";
import { fileHandler } from "@ai-matrx/media/files/engine/handler/handler";
import { composeUploadFolderPath } from "@ai-matrx/media/files";
import {
  ensureExecutionOrganization,
  requireExecutionOrganizationId
} from "../../../redux/execution-system/utils/required-organization.js";
import { attachResourceToConversation } from "./attach-resource.js";
import { useUploadAgentResources } from "./usePasteImageResource.js";
async function uploadCapturedImage(store, conversationId, file) {
  const state = store.getState();
  const organizationId = await ensureExecutionOrganization(state, conversationId) ?? requireExecutionOrganizationId(state, conversationId);
  const uploaded = await fileHandler.upload(
    { kind: "file", file },
    {
      folderPath: composeUploadFolderPath("attachments", "screenshots"),
      visibility: "personal",
      metadata: { scope: { organization_id: organizationId } },
      createShareLink: true,
      shareLinkPermissionLevel: "viewer"
    }
  );
  if (!uploaded.fileId) throw new Error("The screenshot upload returned no file id");
  return { fileId: uploaded.fileId, url: uploaded.url ?? null };
}
function screenshotName(title) {
  const base = title.trim().replace(/[^\w\s.-]+/g, "").trim().slice(0, 60) || "page";
  return `${base} screenshot.png`;
}
function useAttachRenderedArtifact(conversationId) {
  const dispatch = useAppDispatch();
  const store = useAppStore();
  const uploadResources = useUploadAgentResources(conversationId ?? "", {
    uploadRoot: "attachments",
    uploadPath: "screenshots"
  });
  return (args) => attachRenderedArtifact(
    { dispatch, getState: store.getState },
    conversationId,
    args,
    uploadResources
  );
}
async function attachRenderedArtifact(store, conversationId, { source, representation, capture }, uploadFiles) {
  const { dispatch } = store;
  if (!conversationId) {
    toast.error("Open a chat to attach this to.");
    return false;
  }
  if (capture) registerRenderedArtifactCapture(source, capture);
  if (representation !== "screenshot") {
    const resourceId = generateResourceId();
    dispatch(
      addResource({
        conversationId,
        blockType: RENDERED_ARTIFACT_BLOCK_TYPE,
        resourceId,
        source,
        options: { representation }
      })
    );
    dispatch(
      setResourcePreview({
        conversationId,
        resourceId,
        preview: `${source.title || "Artifact"} \xB7 ${renderedArtifactRepresentationLabel(source, representation)}`
      })
    );
    return true;
  }
  if (!capture) {
    toast.error("This item can't be captured as an image.");
    return false;
  }
  const name = screenshotName(source.title);
  const placeholderId = generateResourceId();
  dispatch(
    addResource({
      conversationId,
      blockType: "image",
      resourceId: placeholderId,
      source: { filename: name, mime_type: "image/png" }
    })
  );
  try {
    const result = await capture();
    const state = store.getState();
    if (state.instanceResources.byConversationId[conversationId]?.[placeholderId] === void 0) {
      return false;
    }
    if (result.kind === "file" && uploadFiles) {
      dispatch(removeResource({ conversationId, resourceId: placeholderId }));
      await uploadFiles([result.file]);
      return true;
    }
    const stored = result.kind === "file" ? await uploadCapturedImage(store, conversationId, result.file) : result;
    const attached = await attachResourceToConversation(store, conversationId, {
      type: "file",
      data: {
        id: stored.fileId,
        filename: name,
        url: stored.url ?? void 0,
        type: "image/png",
        mime_type: "image/png",
        details: { filename: name }
      }
    });
    if (!attached) throw new Error("The screenshot could not be attached");
    dispatch(removeResource({ conversationId, resourceId: placeholderId }));
    return true;
  } catch (err) {
    const reason = err instanceof Error ? err.message : "Capture failed";
    dispatch(
      setResourceStatus({
        conversationId,
        resourceId: placeholderId,
        status: "error",
        errorMessage: reason
      })
    );
    toast.error(`Couldn't capture the page: ${reason}`);
    return false;
  }
}
export {
  attachRenderedArtifact,
  useAttachRenderedArtifact
};
