      const resolvedValue = binding.contextItemId ? resolved.values[binding.contextItemId] ?? null : null;
      const source = binding.contextItemId ? resolved.sourcePerKey[binding.contextItemId] : void 0;
      const activeScopeIdOfType = activeIdsByType[binding.scopeTypeId]?.[0] ?? null;
      const scopeActive = !!activeScopeIdOfType;
