function groupMessageIds(group) {
  switch (group.kind) {
    case "user":
    case "collab-note":
      return [group.messageId];
    case "assistant-failed":
      return group.messageId ? [group.messageId] : [];
    case "assistant":
    case "examples":
      return group.members.map((m) => m.messageId).filter((id) => typeof id === "string");
  }
}
function filterGroupsToPinned(groups, pinned) {
  return groups.filter((g) => groupMessageIds(g).some((id) => pinned.has(id)));
}
function groupsToRender(args) {
  if (args.pinnedOnly) return filterGroupsToPinned(args.all, args.pinned);
  if (args.findOpen) return args.all;
  return args.windowed;
}
export {
  filterGroupsToPinned,
  groupMessageIds,
  groupsToRender
};
