function readVisibleText(element) {
  const visibleText = element.innerText?.trim();
  if (visibleText) return visibleText;
  const clone = element.cloneNode(true);
  clone.querySelectorAll("style, script, template, noscript").forEach((node) => node.remove());
  return clone.textContent?.trim() ?? "";
}
function resolveMarkdownContext(target, conversationId) {
  const ctx = {
    conversationId,
    conversation_id: conversationId
  };
  if (!target) return ctx;
  const messageEl = target.closest("[data-message-id]");
  if (messageEl?.dataset.messageId) {
    ctx.messageId = messageEl.dataset.messageId;
    ctx.message_id = messageEl.dataset.messageId;
  }
  const blockEl = target.closest('[data-mtx-ctx="block"]');
  if (blockEl) {
    const d = blockEl.dataset;
    if (d.blockId) {
      ctx.blockId = d.blockId;
      ctx.block_id = d.blockId;
    }
    if (d.blockType) {
      ctx.blockType = d.blockType;
      ctx.block_type = d.blockType;
    }
    if (d.toolName) {
      ctx.toolName = d.toolName;
      ctx.tool_name = d.toolName;
    }
    if (d.language) ctx.language = d.language;
    if (d.artifactType) {
      ctx.artifactType = d.artifactType;
      ctx.artifact_type = d.artifactType;
    }
    if (d.artifactId) {
      ctx.artifactId = d.artifactId;
      ctx.artifact_id = d.artifactId;
    }
    if (d.blockSource) {
      ctx.diagram_source = d.blockSource;
      ctx.content = d.blockSource;
    } else {
      const text = readVisibleText(blockEl);
      if (text) ctx.content = text;
    }
  } else if (messageEl) {
    const contentEl = messageEl.querySelector("[data-message-content]") ?? messageEl;
    const text = readVisibleText(contentEl);
    if (text) ctx.content = text;
  }
  return ctx;
}
export {
  resolveMarkdownContext
};
