import { toast } from "../../../host/notify.js";
import { copyToHostClipboard } from "../../../host/clipboard.js";
import { toastDoor } from "../../../host/ui-slots.js";
import { openOverlay, CHAT_WINDOWS } from "../../../host/windows.js";
import {
  duplicateConversation,
  renameConversation
} from "../../redux/conversation-list/conversation-row-actions.thunks.js";
import { conversationRenameOpener } from "./rename/conversationRenameOpener.js";
import { conversationTitleText } from "@ai-matrx/content-ir/surfaces";
function displayConversationTitle(title) {
  if (!title) return "Untitled conversation";
  return title.trim().length > 0 ? conversationTitleText(title) ?? title : "Untitled conversation";
}
function conversationTitleFromState(state, conversationId) {
  return state.conversationList?.byConversationId?.[conversationId]?.title ?? state.conversations?.byConversationId?.[conversationId]?.title ?? null;
}
function canonicalConversationHref(conversationId) {
  return `/chat/${conversationId}`;
}
function resolveAbsoluteHref(href) {
  if (typeof window === "undefined") return href;
  if (/^https?:\/\//i.test(href)) return href;
  return `${window.location.origin}${href.startsWith("/") ? href : `/${href}`}`;
}
async function copyConversationLink(href) {
  await copyToHostClipboard(resolveAbsoluteHref(href), "Link copied");
}
function shareConversation(dispatch, conversationId, title) {
  dispatch(
    openOverlay({
      overlayId: CHAT_WINDOWS.shareModal,
      data: {
        resourceType: "conversation",
        resourceId: conversationId,
        resourceName: displayConversationTitle(title)
      }
    })
  );
}
function makeAgentFromConversation(dispatch, conversationId, title) {
  dispatch(
    openOverlay({
      overlayId: CHAT_WINDOWS.agentFromChatWindow,
      data: { conversationId, conversationTitle: displayConversationTitle(title) }
    })
  );
}
async function duplicateConversationVerb(dispatch, conversationId, options = {}) {
  const result = await dispatch(
    duplicateConversation({ conversationId, surfaceKey: options.surfaceKey })
  );
  if (duplicateConversation.rejected.match(result)) {
    toast.error(result.payload?.message ?? "Duplicate failed");
    return;
  }
  toast.success("Conversation duplicated", {
    action: toastDoor("conversation", result.payload.newConversationId)
  });
  options.onSuccess?.();
}
async function renameConversationTitle(dispatch, conversationId, title) {
  const result = await dispatch(renameConversation({ conversationId, title }));
  if (renameConversation.rejected.match(result)) {
    toast.error(result.payload?.message ?? "Rename failed");
    return false;
  }
  toast.success("Conversation renamed");
  return true;
}
function openConversationRename(conversationId, title) {
  void conversationRenameOpener.open({ conversationId, title });
}
export {
  canonicalConversationHref,
  conversationTitleFromState,
  copyConversationLink,
  displayConversationTitle,
  duplicateConversationVerb,
  makeAgentFromConversation,
  openConversationRename,
  renameConversationTitle,
  shareConversation
};
