"use client";
import { buildUserToolOverrides } from "../../agents/redux/execution-system/utils/build-tool-injection.js";
import { useEffect, useRef, useState } from "react";
import { useAppDispatch, useAppSelector, useAppStore } from "../../store/hooks.js";
import { useAgentLauncher } from "../../agents/hooks/useAgentLauncher.js";
import { setUserInputText } from "../../agents/redux/execution-system/instance-user-input/instance-user-input.slice.js";
import { smartExecute } from "../../agents/redux/execution-system/thunks/smart-execute.thunk.js";
import { selectLatestAnswerText } from "../../agents/redux/execution-system/selectors/aggregate.selectors.js";
import { useVoiceAgentInstance } from "../hooks/useVoiceAgentInstance.js";
import { useRealtimeAgentConfig } from "../hooks/useRealtimeAgentConfig.js";
import { useXaiVoiceSession } from "../hooks/useXaiVoiceSession.js";
import { usePersistVoiceTranscript } from "../hooks/usePersistVoiceTranscript.js";
import { applyAgentConfig } from "../state/voiceAgentSlice.js";
import { selectVoiceTools } from "../state/selectors.js";
import {
  createVoiceRelayController
} from "./relayController.js";
import { createUtteranceQueue } from "./utteranceQueue.js";
import {
  COMMUNICATION_LEDGER_TOOL,
  COMMUNICATION_LEDGER_TOOL_NAME,
  disposeLedger,
  getOrCreateLedger,
  registerCommunicationLedgerTool
} from "./questionLedger.js";
import {
  removeContextEntry,
  setContextEntry
} from "../../agents/redux/execution-system/instance-context/instance-context.slice.js";
import { MANDATE_KEYS } from "@ai-matrx/agents/mandates";
import { kindTextToMarkdown } from "@ai-matrx/content-ir/surfaces";
const VOICE_COMMUNICATOR_MANDATE_KEY = MANDATE_KEYS.voice__communicator;
const NARRATION_DELAY_MS = 2500;
registerCommunicationLedgerTool();
function useVoiceRelaySession(opts) {
  const {
    communicatorAgentId,
    primaryAgentId,
    conversationId: pinnedConversationId,
    surfaceKey,
    sourceFeature,
    surface,
    questionPacing
  } = opts;
  const effectiveSurface = surface ?? "matrx-user/chat-voice";
  const pacingRef = useRef(questionPacing ?? "one_at_a_time");
  useEffect(() => {
    pacingRef.current = questionPacing ?? "one_at_a_time";
  }, [questionPacing]);
  const dispatch = useAppDispatch();
  const store = useAppStore();
  const instanceId = useVoiceAgentInstance({
    preset: "intro",
    agentId: communicatorAgentId,
    // Every relay runs the SAME Communicator agent, so the agent id alone
    // cannot key the voice instance — scope it to the host surface or two
    // relays on one page share a session. See the prop's own docs.
    instanceScope: surfaceKey
  });
  const { conversationId: launcherConversationId } = useAgentLauncher(
    primaryAgentId,
    {
      surfaceKey,
      sourceFeature,
      conversationId: pinnedConversationId,
      config: { responseDensity: "compact" },
      // A voice session outliving a remount must keep its brain conversation.
      retainOnUnmount: true
    }
  );
  const conversationId = pinnedConversationId ?? launcherConversationId;
  const toolDecisionsKey = useAppSelector((s) => {
    if (!conversationId) return "[[],null]";
    const { add, ...rest } = buildUserToolOverrides(s, conversationId);
    return JSON.stringify([add ?? [], Object.keys(rest).length > 0 ? rest : null]);
  });
  const [addedToolIds, userOverrides] = JSON.parse(toolDecisionsKey);
  useRealtimeAgentConfig({
    instanceId,
    agentId: communicatorAgentId,
    surface: effectiveSurface,
    addedToolIds,
    userOverrides
  });
  const conversationIdRef = useRef(null);
  useEffect(() => {
    conversationIdRef.current = conversationId ?? null;
  }, [conversationId]);
  const [controller, setController] = useState(null);
  const pendingUtterancesRef = useRef(null);
  useEffect(() => {
    const pendingUtterances = createUtteranceQueue();
    pendingUtterancesRef.current = pendingUtterances;
    const created = createVoiceRelayController({
      onUserUtterance: (transcript) => {
        const targetConversationId = conversationIdRef.current;
        if (!targetConversationId) {
          pendingUtterances.enqueue(transcript);
          return;
        }
        dispatch(setUserInputText({ conversationId: targetConversationId, text: transcript }));
        void dispatch(smartExecute({ conversationId: targetConversationId }));
      },
      // THE SIDE CHANNEL (ruling 6): everything spoken in the voice layer is
      // published into the brain conversation's context, so EVERY send —
      // typed or spoken — carries it without polluting the user's message
      // bubble. The rich value raises max_inline_chars to the 5000 ceiling
      // and the block is budgeted under it (sideChannel), so it is INLINED
      // into the prompt — model-visible with no ctx_get round-trip. It also
      // renders as a labeled context chip on the user's message: deliberate
      // (ruling 1 — the text is never hidden; the chip is the receipt of
      // exactly what the brain was told).
      onExchangeUpdated: (serializedBlock) => {
        const targetConversationId = conversationIdRef.current;
        if (!targetConversationId) return;
        if (serializedBlock) {
          dispatch(
            setContextEntry({
              conversationId: targetConversationId,
              key: "voice_exchange",
              value: {
                content: serializedBlock,
                type: "text",
                label: "Spoken conversation (voice layer)",
                max_inline_chars: 5e3
              },
              type: "text",
              label: "Spoken conversation (voice layer)"
            })
          );
        } else {
          dispatch(
            removeContextEntry({
              conversationId: targetConversationId,
              key: "voice_exchange"
            })
          );
        }
      }
    });
    setController(created);
    return () => {
      created.dispose();
      disposeLedger(instanceId);
      pendingUtterances.clear();
      if (pendingUtterancesRef.current === pendingUtterances) {
        pendingUtterancesRef.current = null;
      }
    };
  }, [dispatch, instanceId]);
  useEffect(() => {
    const queue = pendingUtterancesRef.current;
    if (!controller || !conversationId || !queue || queue.size() === 0) return;
    queue.flush((utterance) => {
      dispatch(
        setUserInputText({ conversationId, text: utterance.text })
      );
      void dispatch(smartExecute({ conversationId }));
    });
  }, [controller, conversationId, dispatch]);
  const tools = useAppSelector((s) => selectVoiceTools(s, instanceId));
  useEffect(() => {
    if (tools.some((t) => t.name === COMMUNICATION_LEDGER_TOOL_NAME)) return;
    dispatch(
      applyAgentConfig({
        instanceId,
        tools: [...tools, COMMUNICATION_LEDGER_TOOL]
      })
    );
  }, [dispatch, instanceId, tools]);
  const session = useXaiVoiceSession({
    instanceId,
    agentId: communicatorAgentId,
    surface: effectiveSurface,
    addedToolIds,
    userOverrides,
    relay: controller?.binding
  });
  usePersistVoiceTranscript({ instanceId });
  const brainStatus = useAppSelector(
    (s) => conversationId ? s.conversations?.byConversationId[conversationId]?.status ?? "ready" : "ready"
  );
  const brainBusy = brainStatus === "running" || brainStatus === "streaming" || brainStatus === "paused";
  const prevStatusRef = useRef("ready");
  const narrationTimerRef = useRef(null);
  useEffect(() => {
    const prev = prevStatusRef.current;
    prevStatusRef.current = brainStatus;
    if (!controller || brainStatus === prev) return;
    const clearNarrationTimer = () => {
      if (narrationTimerRef.current) {
        clearTimeout(narrationTimerRef.current);
        narrationTimerRef.current = null;
      }
    };
    const wasActive = prev === "running" || prev === "streaming" || prev === "paused";
    if ((brainStatus === "running" || brainStatus === "streaming") && !wasActive) {
      controller.drainVoiceExchange();
      clearNarrationTimer();
      narrationTimerRef.current = setTimeout(() => {
        controller.speakMirror();
      }, NARRATION_DELAY_MS);
      return;
    }
    if (!wasActive) return;
    clearNarrationTimer();
    switch (brainStatus) {
      case "paused":
        controller.speakNarration(
          "The primary agent is finishing a step before answering."
        );
        return;
      case "error":
      case "cancelled":
        controller.speakNarration(
          brainStatus === "error" ? "The primary agent hit a problem with that message \u2014 the user can try again." : "That request was stopped \u2014 the user can continue whenever they like."
        );
        controller.clearAwaitingBrain();
        return;
      case "complete": {
        if (!conversationId) return;
        const answer = selectLatestAnswerText(conversationId)(store.getState());
        if (answer.trim().length > 0) {
          controller.speakDelivery(kindTextToMarkdown(answer), {
            ledgerSummary: getOrCreateLedger(instanceId).serialize(),
            pacing: pacingRef.current
          });
        } else {
          controller.clearAwaitingBrain();
        }
        return;
      }
      default:
        return;
    }
  }, [brainStatus, controller, conversationId, instanceId, store]);
  useEffect(() => {
    return () => {
      if (narrationTimerRef.current) clearTimeout(narrationTimerRef.current);
    };
  }, []);
  const sendToPrimary = (text) => {
    const targetConversationId = conversationIdRef.current;
    if (!targetConversationId || !text.trim()) return;
    controller?.markAwaitingBrain();
    dispatch(setUserInputText({ conversationId: targetConversationId, text }));
    void dispatch(smartExecute({ conversationId: targetConversationId }));
  };
  return {
    ...session,
    instanceId,
    primaryConversationId: conversationId ?? null,
    brainBusy,
    sendToPrimary,
    pendingUtteranceCount: () => pendingUtterancesRef.current?.size() ?? 0
  };
}
export {
  VOICE_COMMUNICATOR_MANDATE_KEY,
  useVoiceRelaySession
};
