import { createAsyncThunk } from "@reduxjs/toolkit";
import { supabase } from "../../../host/db.js";
import { assertWriteLanded, describeWriteFailure, tryWriteOne } from "@ai-matrx/data/db";
import { favoritesService } from "../../../context/sources/scopes.js";
import { isScopesRpcErr } from "../../../context/sources/scopes.js";
import {
  patchConversation,
  renameConversation as renameConversationListItem,
  revertRename,
  addToTrash,
  removeFromTrash
} from "./conversation-list.slice.js";
import { findConversationRow } from "./conversation-list.selectors.js";
import { patchConversationInScopes } from "../conversation-history/slice.js";
import { patchConversation as patchConversationRecord } from "../execution-system/conversations/conversations.slice.js";
import { setConversationLabel as setMessagesConversationLabel } from "../execution-system/messages/messages.slice.js";
import {
  setConversationLabel as setInstancesConversationLabel,
  patchConversation as patchInstanceConversation
} from "../execution-system/conversations/conversations.slice.js";
import { selectConversationIsEphemeral } from "../execution-system/conversations/conversations.selectors.js";
import { forkConversationServer } from "../execution-system/message-crud/server/fork-conversation-server.thunk.js";
function refusalWords(err, action) {
  const w = describeWriteFailure(err, { action, remedy: "Try again." });
  return `${w.title} ${w.description}`;
}
function landedOrRefusal(rows, technical) {
  try {
    assertWriteLanded(rows, technical);
    return null;
  } catch (e) {
    return e;
  }
}
const renameConversation = createAsyncThunk(
  "conversationRow/rename",
  async ({ conversationId, title }, { dispatch, getState, rejectWithValue }) => {
    const trimmed = title.trim();
    const nextTitle = trimmed.length > 0 ? trimmed : null;
    const previousTitle = getState().conversationList.byConversationId[conversationId]?.title ?? null;
    dispatch(
      renameConversationListItem({ conversationId, title: nextTitle ?? "" })
    );
    dispatch(
      patchConversationInScopes({
        conversationId,
        patch: { title: nextTitle }
      })
    );
    dispatch(
      setMessagesConversationLabel({
        conversationId,
        title: nextTitle ?? "",
        description: getState().messages.byConversationId[conversationId]?.description ?? null,
        keywords: getState().messages.byConversationId[conversationId]?.keywords ?? null
      })
    );
    dispatch(
      setInstancesConversationLabel({
        conversationId,
        title: nextTitle
      })
    );
    const { error } = await tryWriteOne(
      supabase.schema("chat").from("conversation").update({ title: nextTitle, updated_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("id", conversationId).select("id"),
      { action: "rename", noun: "conversation" }
    );
    if (error) {
      dispatch(revertRename({ conversationId, previousTitle }));
      dispatch(
        patchConversationInScopes({
          conversationId,
          patch: { title: previousTitle }
        })
      );
      dispatch(
        setInstancesConversationLabel({
          conversationId,
          title: previousTitle
        })
      );
      return rejectWithValue({ message: error.message });
    }
    return { conversationId, title: nextTitle };
  }
);
const setConversationFavorite = createAsyncThunk(
  "conversationRow/setFavorite",
  async ({ conversationId, isFavorite }, { dispatch, rejectWithValue }) => {
    const result = await favoritesService.setFavorite(
      "conversation",
      conversationId,
      isFavorite
    );
    if (isScopesRpcErr(result)) {
      return rejectWithValue({
        message: refusalWords(result.error, isFavorite ? "pin this conversation" : "unpin this conversation")
      });
    }
    dispatch(patchConversation({ conversationId, patch: { isFavorite } }));
    dispatch(
      patchConversationInScopes({ conversationId, patch: { isFavorite } })
    );
    return { conversationId, isFavorite };
  }
);
const setConversationArchived = createAsyncThunk(
  "conversationRow/setArchived",
  async ({ conversationId, archived }, { dispatch, getState, rejectWithValue }) => {
    const before = findConversationRow(getState(), conversationId);
    const nextStatus = archived ? "archived" : "active";
    const action = archived ? "archive this conversation" : "restore this conversation";
    const { data, error } = await supabase.schema("chat").from("conversation").update({ status: nextStatus, updated_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("id", conversationId).select("id");
    const refusal = error ?? landedOrRefusal(data, `chat.conversation status=${nextStatus} ${conversationId}`);
    if (refusal) return rejectWithValue({ message: refusalWords(refusal, action) });
    dispatch(
      patchConversation({ conversationId, patch: { status: nextStatus } })
    );
    dispatch(
      patchConversationInScopes({
        conversationId,
        patch: { status: nextStatus }
      })
    );
    dispatch(
      patchConversationRecord({ conversationId, persistedStatus: nextStatus })
    );
    if (archived) {
      if (before) dispatch(addToTrash({ ...before, status: nextStatus }));
    } else {
      dispatch(removeFromTrash(conversationId));
    }
    return { conversationId, status: nextStatus };
  }
);
const setConversationExcludeFromKg = createAsyncThunk(
  "conversationRow/setExcludeFromKg",
  async ({ conversationId, excludeFromKg }, { dispatch, rejectWithValue }) => {
    const { data, error } = await supabase.schema("chat").from("conversation").update({
      exclude_from_kg: excludeFromKg,
      updated_at: (/* @__PURE__ */ new Date()).toISOString()
    }).eq("id", conversationId).select("id");
    const refusal = error ?? landedOrRefusal(data, `chat.conversation exclude_from_kg=${excludeFromKg} ${conversationId}`);
    if (refusal) {
      return rejectWithValue({
        message: refusalWords(
          refusal,
          excludeFromKg ? "exclude this conversation from the knowledge graph" : "include this conversation in the knowledge graph"
        )
      });
    }
    dispatch(patchConversation({ conversationId, patch: { excludeFromKg } }));
    dispatch(
      patchConversationInScopes({
        conversationId,
        patch: { excludeFromKg }
      })
    );
    return { conversationId, excludeFromKg };
  }
);
const duplicateConversation = createAsyncThunk(
  "conversationRow/duplicate",
  async ({ conversationId, title, surfaceKey }, { dispatch, getState, rejectWithValue }) => {
    const sourceTitle = getState().conversationList.byConversationId[conversationId]?.title ?? null;
    const defaultTitle = sourceTitle ? `Copy of ${sourceTitle}` : "Copy of conversation";
    const result = await dispatch(
      forkConversationServer({
        conversationId,
        title: title ?? defaultTitle,
        surfaceKey
      })
    );
    if (forkConversationServer.rejected.match(result)) {
      const message = result.payload?.message ?? result.error.message ?? "Duplicate failed";
      return rejectWithValue({ message });
    }
    return {
      conversationId,
      newConversationId: result.payload.conversationId
    };
  }
);
const setConversationSandbox = createAsyncThunk(
  "conversationRow/setSandbox",
  async ({ conversationId, ref }, { dispatch, getState, rejectWithValue }) => {
    const state = getState();
    const record = state.conversations.byConversationId[conversationId];
    const previous = record?.sandboxBinding ?? null;
    const previousPersisted = record?.sandboxBindingPersisted ?? false;
    dispatch(
      patchInstanceConversation({
        conversationId,
        sandboxBinding: ref,
        sandboxBindingPersisted: false
      })
    );
    const isEphemeral = selectConversationIsEphemeral(conversationId)(state);
    if (isEphemeral || (record?.cacheOnly ?? true)) {
      return { conversationId, persisted: false };
    }
    const { data: row, error: readError } = await supabase.schema("chat").from("conversation").select("metadata").eq("id", conversationId).single();
    if (readError) {
      dispatch(
        patchInstanceConversation({
          conversationId,
          sandboxBinding: previous,
          sandboxBindingPersisted: previousPersisted
        })
      );
      return rejectWithValue({ message: readError.message });
    }
    const metadata = typeof row?.metadata === "object" && row.metadata !== null ? { ...row.metadata } : {};
    const setOrDelete = (key, value) => {
      if (value) metadata[key] = value;
      else delete metadata[key];
    };
    setOrDelete("sandbox_override_proxy_url", ref?.proxyUrl || void 0);
    setOrDelete("sandbox_override_tier", ref?.tier);
    setOrDelete("sandbox_override_name", ref?.name);
    delete metadata["sandbox_override_kind"];
    const isLocalPc = ref?.kind === "local-pc";
    const columnPatch = {
      sandbox_instance_id: ref && !isLocalPc ? ref.rowId : null,
      app_instance_id: ref && isLocalPc ? ref.rowId : null
    };
    const { error } = await tryWriteOne(
      supabase.schema("chat").from("conversation").update({
        ...columnPatch,
        metadata,
        updated_at: (/* @__PURE__ */ new Date()).toISOString()
      }).eq("id", conversationId).select("id"),
      { action: "change", noun: "conversation" }
    );
    if (error) {
      dispatch(
        patchInstanceConversation({
          conversationId,
          sandboxBinding: previous,
          sandboxBindingPersisted: previousPersisted
        })
      );
      return rejectWithValue({ message: error.message });
    }
    dispatch(
      patchInstanceConversation({
        conversationId,
        sandboxBindingPersisted: true
      })
    );
    return { conversationId, persisted: true };
  }
);
export {
  duplicateConversation,
  renameConversation,
  setConversationArchived,
  setConversationExcludeFromKg,
  setConversationFavorite,
  setConversationSandbox
};
