import { createAsyncThunk } from "@reduxjs/toolkit";
import { supabase } from "../../../../host/db.js";
import { markCacheBypass } from "./cache-bypass.slice.js";
import { invalidateConversationCache } from "./invalidate-conversation-cache.thunk.js";
import { executeInstance } from "../thunks/execute-instance.thunk.js";
import { loadConversation } from "../thunks/load-conversation.thunk.js";
import { selectRegenerateAnchor } from "./regenerate-anchor.js";
const regenerateAnswer = createAsyncThunk(
  "messages/regenerateAnswer",
  async ({ conversationId, assistantMessageId }, { dispatch, getState, rejectWithValue }) => {
    const anchor = selectRegenerateAnchor(getState(), conversationId, assistantMessageId);
    if (!anchor) {
      return rejectWithValue({
        message: "Only the latest answer can be regenerated here \u2014 use Fork for an earlier one."
      });
    }
    let userPosition = anchor.userPosition;
    if (userPosition === null) {
      const { data, error: readErr } = await supabase.schema("chat").from("message").select("position").eq("conversation_id", conversationId).eq("role", "user").is("deleted_at", null).order("position", { ascending: false }).limit(1).maybeSingle();
      if (readErr || typeof data?.position !== "number") {
        console.error("[regenerateAnswer] could not find the question", readErr);
        return rejectWithValue({
          message: "Couldn't find the question this answer replied to."
        });
      }
      userPosition = data.position;
    }
    const { error } = await supabase.rpc("cx_truncate_conversation_after", {
      p_conversation_id: conversationId,
      p_after_position: userPosition
    });
    if (error) {
      console.error("[regenerateAnswer] truncate failed", error);
      return rejectWithValue({ message: error.message ?? "Couldn't archive the current answer" });
    }
    dispatch(markCacheBypass({ conversationId, conversation: true }));
    void dispatch(invalidateConversationCache({ conversationId }));
    try {
      await dispatch(loadConversation({ conversationId })).unwrap();
    } catch (err) {
      console.error("[regenerateAnswer] reload after truncate failed", err);
    }
    void dispatch(executeInstance({ conversationId, retry: true }));
    return { conversationId };
  }
);
export {
  regenerateAnswer
};
