const DELIVERY_CUE_PREFIX = "[cue:deliver]";
const NARRATION_CUE_PREFIX = "[cue:narrate]";
const MIRROR_CUE_PREFIX = "[cue:mirror]";
function buildDeliveryCueText(primaryAgentResponse, opts = {}) {
  const pacing = opts.pacing ?? "one_at_a_time";
  const lines = [
    `${DELIVERY_CUE_PREFIX} The primary agent has replied. Deliver this to the user now, conversationally.`,
    `Pacing mode: ${pacing}`
  ];
  if (opts.speakerRole) {
    lines.push(`Speaking role: ${opts.speakerRole}`);
  }
  lines.push("--- primary agent response ---", primaryAgentResponse.trim());
  if (opts.ledgerSummary && opts.ledgerSummary.trim().length > 0) {
    lines.push("--- open questions ---", opts.ledgerSummary.trim());
  }
  return lines.join("\n");
}
function buildMirrorCueText() {
  return `${MIRROR_CUE_PREFIX} The primary agent is still working on what the user just said. Do NOT answer it, and do NOT guess what the answer will be. In one or two short sentences, reflect back what you understood from their last message so they know they were heard \u2014 then stop and wait for the answer.`;
}
function buildNarrationCueText(narration) {
  return `${NARRATION_CUE_PREFIX} A status update from the system \u2014 the user has NOT received an answer yet. Say ONE short, truthful line reflecting this status; do not answer their question yourself.
Status: ${narration.trim()}`;
}
export {
  DELIVERY_CUE_PREFIX,
  MIRROR_CUE_PREFIX,
  NARRATION_CUE_PREFIX,
  buildDeliveryCueText,
  buildMirrorCueText,
  buildNarrationCueText
};
