import { createAsyncThunk } from "@reduxjs/toolkit";
import { supabase } from "../../../../host/db.js";
import { conversationSandboxBindingFromRow } from "../../../../compute/targets.js";
import { clearSandboxBindingCache } from "../../../../compute/targets.js";
import { patchConversation } from "../conversations/conversations.slice.js";
import {
  selectConversationSandboxBinding,
  selectConversationSandboxPersisted
} from "../conversations/conversations.selectors.js";
const LOG = "[sandbox-binding]";
const refreshConversationSandboxBinding = createAsyncThunk(
  "conversations/refreshSandboxBinding",
  async ({ conversationId }, { getState, dispatch }) => {
    const state = getState();
    const record = state.conversations?.byConversationId?.[conversationId];
    if (!record || record.isEphemeral) return { changed: false };
    const current = selectConversationSandboxBinding(conversationId)(state);
    if (current && !selectConversationSandboxPersisted(conversationId)(state)) {
      return { changed: false };
    }
    const { data, error } = await supabase.schema("chat").from("conversation").select("sandbox_instance_id, app_instance_id, metadata").eq("id", conversationId).is("deleted_at", null).maybeSingle();
    if (error) {
      console.warn(
        `${LOG} could not re-read the compute binding for conversation ${conversationId} \u2014 the panel keeps showing the binding it already has.`,
        error
      );
      return { changed: false };
    }
    if (!data) return { changed: false };
    const next = conversationSandboxBindingFromRow(data);
    if ((next?.rowId ?? null) === (current?.rowId ?? null)) {
      return { changed: false };
    }
    if (next?.rowId) clearSandboxBindingCache(next.rowId);
    console.warn(
      `${LOG} conversation ${conversationId} is bound to ${next?.rowId ?? "(no box)"} on the server \u2014 aligning the UI without a reload (was ${current?.rowId ?? "(no box)"}).`
    );
    dispatch(
      patchConversation({
        conversationId,
        sandboxBinding: next,
        sandboxBindingPersisted: !!next
      })
    );
    return { changed: true };
  }
);
export {
  refreshConversationSandboxBinding
};
